-- Bo sung cac dia diem da them truc tiep vao prod truoc day (Da Nang/TPHCM)
-- nhung chua tung duoc capture thanh migration. Doi chieu truc tiep voi schema
-- va du lieu prod hien tai de dam bao local khop prod 1:1.
INSERT INTO public.locations (
  id, name, name_en, city, district, address, category, style_tag, vibes, price_level, price_per_person, duration_minutes, rating, opening_hours, closing_hours, off_days, phone, google_maps_url, coordinates, hint, hint_en, short_description, short_description_en, long_description, cover_image, images, photos, is_active, is_featured, verified, created_at, updated_at
) VALUES
  ('bad7cbe4-405b-4ec6-b68a-beb3139deca0', 'Hồ Hòa Trung', 'Hoa Trung Lake', 'DN', 'Hòa Vang', 'Xã Hòa Liên & Hòa Ninh, Huyện Hòa Vang', 'Thiên nhiên', 'Thiên nhiên, Hoang sơ, Thư giãn', ARRAY['Thiên nhiên','Hoang sơ','Thư giãn']::text[], 1, 0, 90, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=H%E1%BB%93%20H%C3%B2a%20Trung%2C%20H%C3%B2a%20Vang%2C%20%C4%90%C3%A0%20N%E1%BA%B5ng', '{"lat": 16.0217, "lng": 108.0346}'::jsonb, 'Hồ nước nhân tạo tuyệt đẹp được bao bọc bởi những ngọn đồi thoai thoải. Mùa nước cạn (tháng 8 – 10) đáy hồ biến thành bãi cỏ xanh mướt như thảo nguyên Mông Cổ. Chuẩn bị lều trại, thảm trải, đồ ăn BBQ và nước uống. Nhớ thu dọn 100% rác thải trước khi về để giữ màu xanh cho thảo nguyên hồ.', 'A stunning man-made lake ringed by gently rolling hills. In the dry season (August to October), the exposed lakebed turns into a lush green meadow reminiscent of the Mongolian steppe. Bring a tent, a mat, BBQ food, and drinks, and remember to pack out 100% of your trash to keep the lake''s "grassland" green.', 'Hồ nước nhân tạo tuyệt đẹp được bao bọc bởi những ngọn đồi thoai thoải. Mùa nước cạn (tháng 8 – 10) đáy hồ biến thành bãi cỏ xanh mướt như thảo nguyên Mông Cổ.', 'A stunning man-made lake ringed by gently rolling hills. In the dry season (August to October), the exposed lakebed turns into a lush green meadow reminiscent of the Mongolian steppe.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/ho-hoa-trung/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/ho-hoa-trung/1.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('65d9e5e2-e869-4ae8-b2a3-d329d36fad98', 'Bảo Tàng Phụ Nữ Nam Bộ', 'Southern Women''s Museum', 'SG', 'Quận 3', '202 Võ Thị Sáu, P.7, Quận 3', 'Bảo tàng', 'lịch sử, văn hóa, cảm hứng', ARRAY['Lịch sử','văn hóa','cảm hứng']::text[], 1, 30000, 90, NULL, '07:30', '17:00', 'Thứ 2', '028 3932 5334', NULL, '{"lat": 10.7839, "lng": 106.6882}'::jsonb, 'Những câu chuyện lãng quên giấu sâu trong những bức tường im lặng, chờ bạn khám phá. Hơn mười tám nghìn kỷ vật kể về những bàn tay, những trái tim, những hy sinh mà lịch sử hiếm khi nhắc tên. Hãy bước vào không gian đầy cảm xúc này để tìm lại những giọng nói bị lịch sử che phủ.', 'Forgotten stories lie hidden deep within these silent walls, waiting to be discovered. More than eighteen thousand artifacts speak of the hands, hearts, and sacrifices that history rarely names. Step into this deeply moving space to rediscover voices that history has long overshadowed.', 'Hơn 18.000 hiện vật tôn vinh đóng góp của phụ nữ Việt Nam qua hai cuộc kháng chiến — thường bị bỏ qua nhưng rất đáng ghé.', 'Over 18,000 artifacts honoring the contributions of Vietnamese women through two wars of resistance, often overlooked but well worth a visit.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/bao-tang-phu-nu-nam-bo/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/bao-tang-phu-nu-nam-bo/1.jpg', true, false, true, '2026-07-23T13:26:06.903962+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('23ddae86-a817-4fe8-bd65-0a473cd7cddb', 'Nhà Thờ Tân Định (Nhà Thờ Màu Hồng)', 'Tan Dinh Church (Pink Church)', 'SG', 'Quận 3', '289 Hai Bà Trưng, P.8, Quận 3', 'Di tích tín ngưỡng', 'màu hồng, sống ảo, iconic', ARRAY['màu hồng','Sống ảo','iconic']::text[], 1, 30000, 90, NULL, '05:30', '18:00', NULL, NULL, NULL, '{"lat": 10.7876, "lng": 106.6893}'::jsonb, 'Một điểm thánh dịu dàng với sắc hồng candy như từ trong giấc mơ, nơi ánh sáng sớm mai tỏa rạng qua từng chi tiết cổ kính. Đây là biểu tượng tâm linh độc nhất nơi đây, nơi hàng thế kỷ lịch sử hòa quyện với sự sống ảo của thời đại. Bước vào không gian thiêng liêng này, bạn sẽ cảm nhận được sự kỳ diệu giữa truyền thống và hiện đại.', 'A gentle sacred spot in dreamy candy pink, where early morning light glows through every antique detail. It''s a one-of-a-kind spiritual landmark here, where centuries of history blend with today''s social-media-ready charm. Step into this sacred space and feel the magic where tradition meets modern life.', 'Nhà thờ màu hồng candy độc nhất Việt Nam xây từ 1876 — check-in hot nhất mạng xã hội Sài Gòn, nổi bật nhất vào buổi sáng sớm.', 'Vietnam''s only candy-pink church, built from 1876, the hottest social-media photo spot in Saigon, most striking in the early morning.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/nha-tho-tan-dinh/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/nha-tho-tan-dinh/1.jpg', true, true, true, '2026-07-23T13:26:06.903962+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('429e0f30-96b4-4cc6-ad2a-3a74ac24de00', 'Cầu Mống', 'Rainbow Bridge, Saigon', 'SG', 'Quận 1', 'Nối đường Võ Văn Kiệt (Q1) và Bến Vân Đồn (Q4) qua kênh Bến Nghé', 'Trải nghiệm', 'Check-in, Về đêm, Nhộn nhịp', ARRAY['Check-in','Về đêm','Nhộn nhịp']::text[], 1, 0, 20, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=C%E1%BA%A7u%20M%E1%BB%91ng%2C%20Qu%E1%BA%ADn%201%20%26%20Qu%E1%BA%ADn%204%2C%20TP.%20H%E1%BB%93%20Ch%C3%AD%20Minh', '{"lat": 10.7693, "lng": 106.7024}'::jsonb, 'Cây cầu sắt màu xanh ngọc bích cổ nhất thành phố do công ty Levallois Perret (Pháp, công ty của Gustave Eiffel) xây dựng từ năm 1893. Thân cầu uốn hình vòng cung thanh thoát, hiện dành riêng cho người đi bộ và ngắm các tòa nhà tài chính soi bóng bên dòng kênh xanh. Góc chụp ảnh từ chân cầu hướng về tòa nhà Ngân hàng Nhà nước Việt Nam chi nhánh TP.HCM mang đậm hơi thở cổ điển Đông Dương thế kỷ 20.', 'The city''s oldest jade-green iron bridge, built in 1893 by the Levallois-Perret company (the French firm associated with Gustave Eiffel). Its graceful arched span is now reserved for pedestrians, who can admire the financial towers reflected in the green canal below. The photo angle from the foot of the bridge, looking toward the State Bank of Vietnam''s HCMC branch building, carries a strong early-20th-century Indochine feel.', 'Cây cầu sắt màu xanh ngọc bích cổ nhất thành phố do công ty Levallois Perret (Pháp, công ty của Gustave Eiffel) xây dựng từ năm 1893. Thân cầu uốn hình vòng cung thanh thoát, hiện dành riêng cho người đi bộ và ngắm các t', 'The city''s oldest jade-green iron bridge, built in 1893 by the Levallois-Perret company (the French firm associated with Gustave Eiffel).', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/cau-mong/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/cau-mong/1.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('4129ff82-ca4f-4497-b973-ba7386073ada', 'Bãi biển Mỹ Khê', 'My Khe Beach', 'DN', 'Sơn Trà', 'Dọc đường Võ Nguyên Giáp, P. Phước Mỹ & P. Khuê Mỹ', 'Thiên nhiên', 'Thiên nhiên, Hoang sơ, Thư giãn', ARRAY['Thiên nhiên','Hoang sơ','Thư giãn']::text[], 1, 0, 120, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=B%C3%A3i%20bi%E1%BB%83n%20M%E1%BB%B9%20Kh%C3%AA%2C%20S%C6%A1n%20Tr%C3%A0%20%26%20Ng%C5%A9%20H%C3%A0nh%20S%C6%A1n%2C%20%C4%90%C3%A0%20N%E1%BA%B5ng', '{"lat": 16.0617, "lng": 108.2477}'::jsonb, 'Được tạp chí Forbes vinh danh là 1 trong 6 bãi biển quyến rũ nhất hành tinh với bãi cát trắng mịn trải dài 900m, sóng biển hiền hòa, đầy đủ tiện ích và an toàn tuyệt đối. Khu vực Bãi 2 và Bãi 3 nước êm và có lực lượng cứu hộ túc trực dày đặc nhất, cực kỳ an toàn cho gia đình có trẻ em.', 'Named by Forbes as one of the six most alluring beaches on the planet, with 900m of soft white sand, gentle waves, full amenities, and top-notch safety. The Bai 2 and Bai 3 sections have the calmest water and the heaviest lifeguard presence, making them ideal for families with kids.', 'Được tạp chí Forbes vinh danh là 1 trong 6 bãi biển quyến rũ nhất hành tinh với bãi cát trắng mịn trải dài 900m, sóng biển hiền hòa, đầy đủ tiện ích và an toàn tuyệt đối.', 'Named by Forbes as one of the six most alluring beaches on the planet, with 900m of soft white sand, gentle waves, full amenities, and top-notch safety.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/bai-bien-my-khe/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/bai-bien-my-khe/1.jpg,https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/bai-bien-my-khe/2.jpg,https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/bai-bien-my-khe/3.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('484f598e-aa4a-4cc4-8fd3-45440abfc640', 'Bãi biển Non Nước', 'Non Nuoc Beach', 'DN', 'Ngũ Hành Sơn', 'Đường Trường Sa, P. Hòa Hải, Q. Ngũ Hành Sơn', 'Thiên nhiên', 'Thiên nhiên, Hoang sơ, Thư giãn', ARRAY['Thiên nhiên','Hoang sơ','Thư giãn']::text[], 1, 0, 120, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=B%C3%A3i%20bi%E1%BB%83n%20Non%20N%C6%B0%E1%BB%9Bc%2C%20Ng%C5%A9%20H%C3%A0nh%20S%C6%A1n%2C%20%C4%90%C3%A0%20N%E1%BA%B5ng', '{"lat": 16, "lng": 108.2614}'::jsonb, 'Bãi biển dài 5km thoai thoải uốn lượn dưới chân danh thắng Ngũ Hành Sơn, bờ cát trắng sạch sẽ quy tụ hàng loạt resort 5 sao quốc tế hàng đầu. Bãi biển thoai thoải, thích hợp cho các hoạt động lướt sóng, chèo SUP và tận hưởng không gian yên tĩnh không quá đông đúc.', 'A gently sloping 5km stretch of beach curving beneath the Marble Mountains, with clean white sand lined by top international 5-star resorts. The gentle slope is perfect for surfing, SUP paddling, and enjoying a quiet, uncrowded atmosphere.', 'Bãi biển dài 5km thoai thoải uốn lượn dưới chân danh thắng Ngũ Hành Sơn, bờ cát trắng sạch sẽ quy tụ hàng loạt resort 5 sao quốc tế hàng đầu.', 'A gently sloping 5km stretch of beach curving beneath the Marble Mountains, with clean white sand lined by top international 5-star resorts.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/bai-bien-non-nuoc/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/bai-bien-non-nuoc/1.jpg,https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/bai-bien-non-nuoc/2.jpg,https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/bai-bien-non-nuoc/3.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('14e5faa0-a563-421e-8713-ed9210b6b9c6', 'Bãi Bụt & Bãi Rạng Sơn Trà', 'Bai But & Bai Rang Beaches, Son Tra', 'DN', 'Sơn Trà', 'Dọc cung đường Hoàng Sa, P. Thọ Quang, Q. Sơn Trà', 'Thiên nhiên', 'Thiên nhiên, Hoang sơ, Thư giãn', ARRAY['Thiên nhiên','Hoang sơ','Thư giãn']::text[], 1, 0, 90, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=B%C3%A3i%20B%E1%BB%A5t%20%26%20B%C3%A3i%20R%E1%BA%A1ng%20S%C6%A1n%20Tr%C3%A0%2C%20S%C6%A1n%20Tr%C3%A0%2C%20%C4%90%C3%A0%20N%E1%BA%B5ng', '{"lat": 16.1172, "lng": 108.282}'::jsonb, 'Vịnh biển kín gió với làn nước ngọc bích, bãi cát thoai thoải liền kề ghềnh đá ngầm, các chòi lá nghỉ ngơi phục vụ hải sản tươi rói bắt tại chỗ. Rất thích hợp cho nhóm bạn hoặc gia đình dựng trại nướng BBQ hoặc gọi các món ốc gai, sò điệp nướng mỡ hành ngay tại bờ biển.', 'A sheltered bay with jade-green water and a gentle sandy shore next to rocky reefs, lined with thatched huts serving seafood caught fresh on the spot. Perfect for groups of friends or families to set up a beachside BBQ, or order grilled sea urchin and scallops with scallion oil right on the sand.', 'Vịnh biển kín gió với làn nước ngọc bích, bãi cát thoai thoải liền kề ghềnh đá ngầm, các chòi lá nghỉ ngơi phục vụ hải sản tươi rói bắt tại chỗ.', 'A sheltered bay with jade-green water and a gentle sandy shore next to rocky reefs, lined with thatched huts serving seafood caught fresh on the spot.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/bai-but-bai-rang-son-tra/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/bai-but-bai-rang-son-tra/1.jpg,https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/bai-but-bai-rang-son-tra/2.jpg,https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/bai-but-bai-rang-son-tra/3.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('19a7ee41-b00f-415c-9fbc-4e3cca936af7', 'Bãi Cát Vàng Sơn Trà', 'Son Tra Golden Sand Beach', 'DN', 'Sơn Trà', 'Tiểu khu 62, Bán đảo Sơn Trà', 'Thiên nhiên', 'Thiên nhiên, Hoang sơ, Thư giãn', ARRAY['Thiên nhiên','Hoang sơ','Thư giãn']::text[], 1, 30000, 90, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=B%C3%A3i%20C%C3%A1t%20V%C3%A0ng%20S%C6%A1n%20Tr%C3%A0%2C%20S%C6%A1n%20Tr%C3%A0%2C%20%C4%90%C3%A0%20N%E1%BA%B5ng', '{"lat": 16.119, "lng": 108.284}'::jsonb, 'Bãi cát vàng óng ả nép mình giữa vách núi đá và biển cả xanh biếc, không gian khép kín lý tưởng cho lặn ngắm san hô, chèo thuyền kayak và bắt ốc biển. Nên đi theo tour cano từ bến sông Hàn để vừa thưởng ngoạn cảnh quan vịnh Đà Nẵng vừa cập bến thuận tiện nhất.', 'A golden stretch of sand tucked between rocky cliffs and deep blue sea, in a secluded cove perfect for snorkeling, kayaking, and beachcombing for shells. Best reached by speedboat tour from the Han River pier, which lets you take in the Da Nang bay views along the way.', 'Bãi cát vàng óng ả nép mình giữa vách núi đá và biển cả xanh biếc, không gian khép kín lý tưởng cho lặn ngắm san hô, chèo thuyền kayak và bắt ốc biển.', 'A golden stretch of sand tucked between rocky cliffs and deep blue sea, in a secluded cove perfect for snorkeling, kayaking, and beachcombing for shells.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/bai-cat-vang-son-tra/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/bai-cat-vang-son-tra/1.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('73373ca4-bc1f-47db-a472-96afa7143f11', 'Bán đảo Sơn Trà', 'Son Tra Peninsula', 'DN', 'Sơn Trà', 'Phường Thọ Quang, Quận Sơn Trà (cách trung tâm ~10km)', 'Thiên nhiên', 'Thiên nhiên, Hoang sơ, Thư giãn', ARRAY['Thiên nhiên','Hoang sơ','Thư giãn']::text[], 1, 0, 180, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=B%C3%A1n%20%C4%91%E1%BA%A3o%20S%C6%A1n%20Tr%C3%A0%2C%20S%C6%A1n%20Tr%C3%A0%2C%20%C4%90%C3%A0%20N%E1%BA%B5ng', '{"lat": 16.11, "lng": 108.275}'::jsonb, '''Lá phổi xanh'' của Đà Nẵng với hệ sinh thái rừng giao thoa biển nhiệt đới, nơi cư trú của loài linh trưởng quý hiếm Voọc chà vá chân nâu (Nữ hoàng linh trưởng). Nên dùng xe số hoặc xe ga bánh lớn chuyên dụng. Không cho khỉ ăn để bảo vệ tập tính tự nhiên hoang dã.', 'Da Nang''s "green lung," where tropical forest meets the sea and the rare red-shanked douc langur (the "queen of primates") makes its home. Ride a manual motorbike or a large-wheel scooter built for the terrain, and don''t feed the monkeys, to protect their natural wild behavior.', '''Lá phổi xanh'' của Đà Nẵng với hệ sinh thái rừng giao thoa biển nhiệt đới, nơi cư trú của loài linh trưởng quý hiếm Voọc chà vá chân nâu (Nữ hoàng linh trưởng).', 'Da Nang''s "green lung," where tropical forest meets the sea and the rare red-shanked douc langur (the "queen of primates") makes its home.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/ban-dao-son-tra/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/ban-dao-son-tra/1.jpg,https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/ban-dao-son-tra/2.jpg,https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/ban-dao-son-tra/3.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('99e20489-a510-46ce-bae2-0a644ba86270', 'Bảo tàng Đà Nẵng & Thành Điện Hải', 'Da Nang Museum & Dien Hai Citadel', 'DN', 'Hải Châu', '24 Trần Phú & 42 Bạch Đằng, P. Thạch Thang, Q. Hải Châu', 'Bảo tàng', 'Lịch sử, Giáo dục, Kiến trúc', ARRAY['Lịch sử','Giáo dục','Kiến trúc']::text[], 1, 20000, 60, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=B%E1%BA%A3o%20t%C3%A0ng%20%C4%90%C3%A0%20N%E1%BA%B5ng%20%26%20Th%C3%A0nh%20%C4%90i%E1%BB%87n%20H%E1%BA%A3i%2C%20H%E1%BA%A3i%20Ch%C3%A2u%2C%20%C4%90%C3%A0%20N%E1%BA%B5ng', '{"lat": 16.0763, "lng": 108.2219}'::jsonb, 'Pháo đài quân sự cổ bằng gạch và đá xây dựng từ thời Gia Long (1813), nơi danh tướng Nguyễn Tri Phương chỉ huy quân dân Đà Nẵng bắn phát súng đầu tiên kháng Pháp năm 1858. Khuôn viên thành Điện Hải vừa được trùng tu khang trang với hàng súng thần công cổ hướng ra sông Hàn rất oai nghiêm.', 'An old brick-and-stone military fortress built under Emperor Gia Long in 1813, where general Nguyen Tri Phuong led Da Nang''s troops and people in firing the first shots against the French in 1858. The citadel grounds have been beautifully restored, with rows of ancient cannons still facing the Han River in full grandeur.', 'Pháo đài quân sự cổ bằng gạch và đá xây dựng từ thời Gia Long (1813), nơi danh tướng Nguyễn Tri Phương chỉ huy quân dân Đà Nẵng bắn phát súng đầu tiên kháng Pháp năm 1858.', 'An old brick-and-stone military fortress built under Emperor Gia Long in 1813, where general Nguyen Tri Phuong led Da Nang''s troops and people in firing the first shots against the French in 1858.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/bao-tang-da-nang-thanh-dien-hai/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/bao-tang-da-nang-thanh-dien-hai/1.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('5add5179-e4b4-4cfa-b710-e777c9d6465b', 'Bảo tàng Mỹ thuật Đà Nẵng', 'Da Nang Fine Arts Museum', 'DN', 'Hải Châu', '78 Lê Duẩn, P. Thạch Thang, Q. Hải Châu', 'Bảo tàng', 'Lịch sử, Giáo dục, Kiến trúc', ARRAY['Lịch sử','Giáo dục','Kiến trúc']::text[], 1, 20000, 45, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=B%E1%BA%A3o%20t%C3%A0ng%20M%E1%BB%B9%20thu%E1%BA%ADt%20%C4%90%C3%A0%20N%E1%BA%B5ng%2C%20H%E1%BA%A3i%20Ch%C3%A2u%2C%20%C4%90%C3%A0%20N%E1%BA%B5ng', '{"lat": 16.0708, "lng": 108.221}'::jsonb, 'Không gian nghệ thuật trưng bày hơn 1.000 tác phẩm hội họa, điêu khắc, mỹ thuật dân gian truyền thống và hiện đại của các nghệ sĩ miền Trung – Tây Nguyên. Không gian yên tĩnh, các góc cầu thang gỗ và phòng tranh ánh sáng tự nhiên tạo nên background ''sống ảo'' phong cách nghệ thuật thanh lịch.', 'An art space showcasing over 1,000 paintings, sculptures, and folk and contemporary artworks by artists from Central Vietnam and the Central Highlands. The quiet galleries, wooden staircases, and naturally lit exhibition rooms make an elegant, artsy backdrop for photos.', 'Không gian nghệ thuật trưng bày hơn 1.000 tác phẩm hội họa, điêu khắc, mỹ thuật dân gian truyền thống và hiện đại của các nghệ sĩ miền Trung – Tây Nguyên.', 'An art space showcasing over 1,000 paintings, sculptures, and folk and contemporary artworks by artists from Central Vietnam and the Central Highlands.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/bao-tang-my-thuat-da-nang/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/bao-tang-my-thuat-da-nang/1.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('fe2dba01-b55a-45fc-853f-c10b188e759b', 'Cầu Rồng', 'Dragon Bridge', 'DN', 'Hải Châu', 'Đường Nguyễn Văn Linh nối Võ Văn Kiệt, P. Phước Ninh & P. An Hải Tây', 'Trải nghiệm', 'Check-in, Về đêm, Nhộn nhịp', ARRAY['Check-in','Về đêm','Nhộn nhịp']::text[], 1, 0, 45, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=C%E1%BA%A7u%20R%E1%BB%93ng%2C%20H%E1%BA%A3i%20Ch%C3%A2u%20%26%20S%C6%A1n%20Tr%C3%A0%2C%20%C4%90%C3%A0%20N%E1%BA%B5ng', '{"lat": 16.0613, "lng": 108.2277}'::jsonb, 'Cầu vòm thép hình rồng thời Lý dài 666m vươn ra biển Đông. Biểu diễn phun lửa (9 lượt) và phun nước (3 lượt) lúc 21:00 tối thứ 6, thứ 7, Chủ Nhật và ngày lễ. Đứng xem tại Cầu Tình Yêu hoặc các quán cafe đường Trần Hưng Đạo để có góc ngắm đẹp. Tránh đứng ngay trước đầu rồng khi phun nước để không bị ướt.', 'A 666m steel arch bridge shaped like a Ly-dynasty dragon, stretching out toward the East Sea. It breathes fire (9 bursts) and sprays water (3 bursts) at 9pm on Friday, Saturday, Sunday, and public holidays. Watch from Love Bridge or the cafes along Tran Hung Dao Street for the best view, just don''t stand right in front of the dragon''s head when it sprays water, or you will get soaked.', 'Cầu vòm thép hình rồng thời Lý dài 666m vươn ra biển Đông. Biểu diễn phun lửa (9 lượt) và phun nước (3 lượt) lúc 21:00 tối thứ 6, thứ 7, Chủ Nhật và ngày lễ.', 'A 666m steel arch bridge shaped like a Ly-dynasty dragon, stretching out toward the East Sea. It breathes fire (9 bursts) and sprays water (3 bursts) at 9pm on Friday, Saturday, Sunday, and public holidays.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/cau-rong/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/cau-rong/1.jpg,https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/cau-rong/2.jpg,https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/cau-rong/3.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('89009a0d-f544-49df-9d87-220149a5cea2', 'Cầu Sông Hàn', 'Han River Bridge', 'DN', 'Hải Châu', 'Đường Lê Duẩn nối Phạm Văn Đồng, P. Hải Châu 1 & P. An Hải Bắc', 'Trải nghiệm', 'Check-in, Về đêm, Nhộn nhịp', ARRAY['Check-in','Về đêm','Nhộn nhịp']::text[], 1, 0, 45, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=C%E1%BA%A7u%20S%C3%B4ng%20H%C3%A0n%2C%20H%E1%BA%A3i%20Ch%C3%A2u%20%26%20S%C6%A1n%20Tr%C3%A0%2C%20%C4%90%C3%A0%20N%E1%BA%B5ng', '{"lat": 16.0697, "lng": 108.2246}'::jsonb, 'Cây cầu quay đầu tiên và duy nhất do kỹ sư và nhân dân Đà Nẵng chung sức xây dựng. Trục giữa cầu quay 90 độ mở đường cho tàu thuyền qua lại lúc 23:00 cuối tuần. Đi du thuyền sông Hàn hoặc ngồi các quán trà chanh vỉa hè đường Bạch Đằng lúc 22:30 để xem trọn khoảnh khắc cầu bắt đầu tách trục quay.', 'Vietnam''s first and only swing bridge, built through the combined effort of Da Nang''s engineers and residents. Its central span rotates 90 degrees to let boats pass at 11pm on weekends. Take a Han River cruise or grab a seat at a sidewalk tea stall on Bach Dang Street around 10:30pm to catch the whole bridge-opening moment.', 'Cây cầu quay đầu tiên và duy nhất do kỹ sư và nhân dân Đà Nẵng chung sức xây dựng. Trục giữa cầu quay 90 độ mở đường cho tàu thuyền qua lại lúc 23:00 cuối tuần.', 'Vietnam''s first and only swing bridge, built through the combined effort of Da Nang''s engineers and residents. Its central span rotates 90 degrees to let boats pass at 11pm on weekends.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/cau-song-han/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/cau-song-han/1.jpg,https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/cau-song-han/2.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('50d37f81-d9ec-4a90-99a1-e1efbf2ddeab', 'Cầu Thuận Phước', 'Thuan Phuoc Bridge', 'DN', 'Hải Châu', 'Nối đường Nguyễn Tất Thành với đường Lê Đức Thọ, P. Thuận Phước', 'Trải nghiệm', 'Check-in, Về đêm, Nhộn nhịp', ARRAY['Check-in','Về đêm','Nhộn nhịp']::text[], 1, 0, 30, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=C%E1%BA%A7u%20Thu%E1%BA%ADn%20Ph%C6%B0%E1%BB%9Bc%2C%20H%E1%BA%A3i%20Ch%C3%A2u%20%26%20S%C6%A1n%20Tr%C3%A0%2C%20%C4%90%C3%A0%20N%E1%BA%B5ng', '{"lat": 16.087, "lng": 108.2206}'::jsonb, 'Cây cầu treo dây võng dài nhất Việt Nam (1.856m) bắc qua cửa sông Hàn đổ ra vịnh Đà Nẵng, mang vẻ đẹp hiện đại và hùng vĩ giữa biển trời. Chân cầu phía Sơn Trà (khu vực bãi cỏ cháy) là tọa độ cắm trại, ngắm hoàng hôn và chụp ảnh phong cách điện ảnh cực kỳ nổi tiếng của giới trẻ Đà Nẵng.', 'Vietnam''s longest suspension bridge (1,856m), spanning the mouth of the Han River where it meets Da Nang Bay, with a sweeping, modern beauty between sea and sky. The Son Tra side of the bridge (the "burnt grass field" area) is a famous spot among Da Nang''s youth for camping, sunset-watching, and cinematic photos.', 'Cây cầu treo dây võng dài nhất Việt Nam (1.856m) bắc qua cửa sông Hàn đổ ra vịnh Đà Nẵng, mang vẻ đẹp hiện đại và hùng vĩ giữa biển trời.', 'Vietnam''s longest suspension bridge (1,856m), spanning the mouth of the Han River where it meets Da Nang Bay, with a sweeping, modern beauty between sea and sky.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/cau-thuan-phuoc/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/cau-thuan-phuoc/1.jpg,https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/cau-thuan-phuoc/2.jpg,https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/cau-thuan-phuoc/3.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('088e30be-62f0-4ecf-953a-0f46a9721ce0', 'Cầu Tình Yêu & Tượng Cá Chép Hóa Rồng', 'Love Bridge & Carp-to-Dragon Statue', 'DN', 'Sơn Trà', 'Bờ Đông sông Hàn, đường Trần Hưng Đạo, P. An Hải Tây', 'Trải nghiệm', 'Check-in, Về đêm, Nhộn nhịp', ARRAY['Check-in','Về đêm','Nhộn nhịp']::text[], 1, 0, 30, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=C%E1%BA%A7u%20T%C3%ACnh%20Y%C3%AAu%20%26%20T%C6%B0%E1%BB%A3ng%20C%C3%A1%20Ch%C3%A9p%20H%C3%B3a%20R%E1%BB%93ng%2C%20S%C6%A1n%20Tr%C3%A0%2C%20%C4%90%C3%A0%20N%E1%BA%B5ng', '{"lat": 16.0679, "lng": 108.2298}'::jsonb, 'Cầu tàu tình yêu với hàng trăm cột đèn lồng hình trái tim đỏ rực rỡ, nơi gắn khóa tình yêu lưu niệm. Tượng Cá Chép Hóa Rồng phun nước trắng xóa bên bờ sông Hàn. Buổi tối lên đèn cực kỳ lung linh. Ngay kế bên là bến du thuyền DHC Marina có quán cafe du thuyền sang trọng để ngắm toàn cảnh cầu Rồng.', 'A pier lined with hundreds of vivid red heart-shaped lanterns, where couples hang padlocks as keepsakes. Nearby, the Carp-to-Dragon Statue sends up sprays of white water on the Han riverbank. It is dazzling once the lights come on at night. Right next door is DHC Marina, with an upscale yacht cafe offering a full view of Dragon Bridge.', 'Cầu tàu tình yêu với hàng trăm cột đèn lồng hình trái tim đỏ rực rỡ, nơi gắn khóa tình yêu lưu niệm. Tượng Cá Chép Hóa Rồng phun nước trắng xóa bên bờ sông Hàn.', 'A pier lined with hundreds of vivid red heart-shaped lanterns, where couples hang padlocks as keepsakes. Nearby, the Carp-to-Dragon Statue sends up sprays of white water on the Han riverbank.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/cau-tinh-yeu-tuong-ca-chep-hoa-rong/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/cau-tinh-yeu-tuong-ca-chep-hoa-rong/1.jpg,https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/cau-tinh-yeu-tuong-ca-chep-hoa-rong/2.jpg,https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/cau-tinh-yeu-tuong-ca-chep-hoa-rong/3.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('70ab1145-599d-4111-8dd5-9d9d28240108', 'Cầu Trần Thị Lý', 'Tran Thi Ly Bridge', 'DN', 'Hải Châu', 'Đường Duy Tân nối Nguyễn Văn Thoại & Ngũ Hành Sơn', 'Trải nghiệm', 'Check-in, Về đêm, Nhộn nhịp', ARRAY['Check-in','Về đêm','Nhộn nhịp']::text[], 1, 0, 30, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=C%E1%BA%A7u%20Tr%E1%BA%A7n%20Th%E1%BB%8B%20L%C3%BD%2C%20H%E1%BA%A3i%20Ch%C3%A2u%2C%20Ng%C5%A9%20H%C3%A0nh%20S%C6%A1n%20%26%20S%C6%A1n%20Tr%C3%A0%2C%20%C4%90%C3%A0%20N%E1%BA%B5ng', '{"lat": 16.0404, "lng": 108.2259}'::jsonb, 'Cầu dây văng một trụ tháp nghiêng độc đáo mang hình dáng cánh buồm no gió vươn ra biển khơi, hệ thống đèn đổi màu rực rỡ về đêm. Dưới chân cầu Trần Thị Lý bờ Đông là ''khu phố ăn vặt chân cầu'' trứ danh với món sữa chua muối và ốc hút nóng hổi giá siêu rẻ.', 'A cable-stayed bridge with a single leaning pylon shaped like a wind-filled sail reaching out to sea, lit up with color-changing lights at night. On the eastern bank beneath the bridge is the famous "bridge-foot snack street," known for salted yogurt and piping-hot snails at dirt-cheap prices.', 'Cầu dây văng một trụ tháp nghiêng độc đáo mang hình dáng cánh buồm no gió vươn ra biển khơi, hệ thống đèn đổi màu rực rỡ về đêm.', 'A cable-stayed bridge with a single leaning pylon shaped like a wind-filled sail reaching out to sea, lit up with color-changing lights at night.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/cau-tran-thi-ly/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/cau-tran-thi-ly/1.jpg,https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/cau-tran-thi-ly/2.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('f42f75fe-480a-48c1-a241-d0f5df5d330c', 'Cầu Vàng & Sun World Bà Nà Hills', 'Golden Bridge & Sun World Ba Na Hills', 'DN', 'Hòa Vang', 'Thôn An Sơn, Xã Hòa Ninh, Huyện Hòa Vang (cách trung tâm ~25km)', 'Trải nghiệm', 'Check-in, Về đêm, Nhộn nhịp', ARRAY['Check-in','Về đêm','Nhộn nhịp']::text[], 4, 900000, 300, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=C%E1%BA%A7u%20V%C3%A0ng%20%26%20Sun%20World%20B%C3%A0%20N%C3%A0%20Hills%2C%20H%C3%B2a%20Vang%2C%20%C4%90%C3%A0%20N%E1%BA%B5ng', '{"lat": 15.9977, "lng": 107.9956}'::jsonb, 'Cây cầu dài 150m ở độ cao 1.414m với đôi bàn tay đá khổng lồ nâng đỡ giữa mây ngàn. Quần thể Làng Pháp, hầm rượu Debay, lâu đài Mặt Trăng và cáp treo kỷ lục. Đi chuyến cáp treo đầu tiên lúc 7:30 sáng để lên Cầu Vàng đầu tiên, vừa săn được mây bồng bềnh vừa tránh được đám đông du khách.', 'A 150m bridge at an elevation of 1,414m, cradled between a pair of giant stone hands amid the clouds. The complex also includes French Village, Debay Wine Cellar, Moon Castle, and a record-setting cable car. Take the first cable car at 7:30am to be among the first on Golden Bridge, catching drifting clouds while beating the crowds.', 'Cây cầu dài 150m ở độ cao 1.414m với đôi bàn tay đá khổng lồ nâng đỡ giữa mây ngàn. Quần thể Làng Pháp, hầm rượu Debay, lâu đài Mặt Trăng và cáp treo kỷ lục.', 'A 150m bridge at an elevation of 1,414m, cradled between a pair of giant stone hands amid the clouds. The complex also includes French Village, Debay Wine Cellar, Moon Castle, and a record-setting cable car.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/cau-vang-sun-world-ba-na-hills/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/cau-vang-sun-world-ba-na-hills/1.jpg,https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/cau-vang-sun-world-ba-na-hills/2.jpg,https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/cau-vang-sun-world-ba-na-hills/3.jpg,https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/cau-vang-sun-world-ba-na-hills/4.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('97470ca7-0aad-47ff-ab52-9b0c9f5f8e52', 'Chợ Cồn', 'Con Market', 'DN', 'Hải Châu', '290 Hùng Vương, P. Vĩnh Trung, Q. Thanh Khê', 'Trải nghiệm', 'Check-in, Về đêm, Nhộn nhịp', ARRAY['Check-in','Về đêm','Nhộn nhịp']::text[], 1, 0, 60, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=Ch%E1%BB%A3%20C%E1%BB%93n%2C%20H%E1%BA%A3i%20Ch%C3%A2u%20%26%20Thanh%20Kh%C3%AA%2C%20%C4%90%C3%A0%20N%E1%BA%B5ng', '{"lat": 16.0696, "lng": 108.2149}'::jsonb, '''Thánh địa ăn vặt'' lớn nhất Đà Nẵng với 2 khu ẩm thực: Đình ẩm thực trong nhà và Phố ẩm thực ngoài trời tụ hội đầy đủ mì Quảng, bún mắm, ốc hút, bánh bèo, nem lụi, chè bưởi. Nên đi với ''bụng đói'' và đi nhóm đông để gọi mỗi gian hàng một ít, thử được trọn vẹn 10+ món đặc sản miền Trung với chi phí siêu rẻ.', 'Da Nang''s biggest street-food haven, with two food zones: an indoor food hall and an outdoor food street serving up mi Quang, bun mam, grilled snails, banh beo, nem lui, and che buoi. Come hungry and bring a big group so you can order a little from every stall, tasting 10+ Central Vietnamese specialties for next to nothing.', '''Thánh địa ăn vặt'' lớn nhất Đà Nẵng với 2 khu ẩm thực: Đình ẩm thực trong nhà và Phố ẩm thực ngoài trời tụ hội đầy đủ mì Quảng, bún mắm, ốc hút, bánh bèo, nem lụi, chè bưởi.', 'Da Nang''s biggest street-food haven, with two food zones: an indoor food hall and an outdoor food street serving up mi Quang, bun mam, grilled snails, banh beo, nem lui, and che buoi.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/cho-con/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/cho-con/1.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('1b1ad397-c1e1-4143-b419-64f0201db3ee', 'Chợ đêm Helio & Helio Center', 'Helio Night Market & Helio Center', 'DN', 'Hải Châu', 'Đường 2 Tháng 9, P. Hòa Cường Bắc, Q. Hải Châu', 'Trải nghiệm', 'Check-in, Về đêm, Nhộn nhịp', ARRAY['Check-in','Về đêm','Nhộn nhịp']::text[], 1, 0, 60, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=Ch%E1%BB%A3%20%C4%91%C3%AAm%20Helio%20%26%20Helio%20Center%2C%20H%E1%BA%A3i%20Ch%C3%A2u%2C%20%C4%90%C3%A0%20N%E1%BA%B5ng', '{"lat": 16.047, "lng": 108.224}'::jsonb, 'Tổ hợp giải trí và chợ đêm ẩm thực quy mô với không gian bài trí ánh sáng nghệ thuật lung linh, sân khấu âm nhạc acoustic live miễn phí mỗi tối. Khu chợ đêm Helio phân chia các gian hàng ẩm thực nướng, bia craft và tráng miệng rất sạch sẽ, có nhiều góc bàn ghế chill ngồi nghe nhạc ngoài trời cực thích.', 'A large entertainment complex and night food market with striking artistic lighting and a free live acoustic stage every evening. Helio''s night market neatly separates its grilled-food, craft beer, and dessert stalls, with plenty of relaxed outdoor seating for enjoying the music.', 'Tổ hợp giải trí và chợ đêm ẩm thực quy mô với không gian bài trí ánh sáng nghệ thuật lung linh, sân khấu âm nhạc acoustic live miễn phí mỗi tối.', 'A large entertainment complex and night food market with striking artistic lighting and a free live acoustic stage every evening.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/cho-dem-helio-helio-center/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/cho-dem-helio-helio-center/1.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('8d905677-51b8-4542-ac83-32a3089151ab', 'Công viên Biển Đông & Bãi Phạm Văn Đồng', 'Bien Dong Park & Pham Van Dong Beach', 'DN', 'Sơn Trà', 'Ngã ba đường Võ Nguyên Giáp & Phạm Văn Đồng, P. Phước Mỹ', 'Thiên nhiên', 'Thiên nhiên, Hoang sơ, Thư giãn', ARRAY['Thiên nhiên','Hoang sơ','Thư giãn']::text[], 1, 0, 60, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=C%C3%B4ng%20vi%C3%AAn%20Bi%E1%BB%83n%20%C4%90%C3%B4ng%20%26%20B%C3%A3i%20Ph%E1%BA%A1m%20V%C4%83n%20%C4%90%E1%BB%93ng%2C%20S%C6%A1n%20Tr%C3%A0%2C%20%C4%90%C3%A0%20N%E1%BA%B5ng', '{"lat": 16.073, "lng": 108.246}'::jsonb, 'Quảng trường biển sôi động nơi thường xuyên tổ chức lễ hội âm nhạc, sự kiện thể thao biển. Đàn chim bồ câu hàng ngàn con sà xuống bãi cát mỗi buổi sáng và chiều. Mua gói thức ăn chim bồ câu giá 10k để chim sà vào tay chụp ảnh check-in như trời Âu. Buổi tối có các ban nhạc đường phố biểu diễn rất vui.', 'A lively beachfront square that regularly hosts music festivals and beach sports events. Thousands of pigeons swoop down onto the sand every morning and evening. Buy a 10k bag of pigeon feed to get them landing on your hand for a European-style photo op. In the evening, street bands perform and keep the vibe lively.', 'Quảng trường biển sôi động nơi thường xuyên tổ chức lễ hội âm nhạc, sự kiện thể thao biển. Đàn chim bồ câu hàng ngàn con sà xuống bãi cát mỗi buổi sáng và chiều.', 'A lively beachfront square that regularly hosts music festivals and beach sports events. Thousands of pigeons swoop down onto the sand every morning and evening.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/cong-vien-bien-dong-bai-pham-van-dong/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/cong-vien-bien-dong-bai-pham-van-dong/1.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('902b4f02-8277-4c04-ac97-f0bf6a0147cb', 'Công viên Vườn tượng APEC', 'APEC Statue Garden Park', 'DN', 'Hải Châu', 'Đường 2 Tháng 9, P. Bình Hiên, Q. Hải Châu', 'Thiên nhiên', 'Thiên nhiên, Hoang sơ, Thư giãn', ARRAY['Thiên nhiên','Hoang sơ','Thư giãn']::text[], 1, 0, 30, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=C%C3%B4ng%20vi%C3%AAn%20V%C6%B0%E1%BB%9Dn%20t%C6%B0%E1%BB%A3ng%20APEC%2C%20H%E1%BA%A3i%20Ch%C3%A2u%2C%20%C4%90%C3%A0%20N%E1%BA%B5ng', '{"lat": 16.059, "lng": 108.223}'::jsonb, 'Mái vòm uốn lượn mang hình tượng ''Cánh diều bay cao'' bằng kết cấu thép khổng lồ rộng gần 800m2, công viên cây xanh, đài phun nước và vườn tượng nghệ thuật 21 nền kinh tế APEC. Lên tầng 2 dưới vòm cánh diều đón gió sông Hàn lồng lộng và chụp ảnh với góc nhìn toàn cảnh Cầu Rồng và Cầu Trần Thị Lý cực kỳ sang xịn.', 'A sweeping steel dome shaped like a "soaring kite," spanning nearly 800 square meters, set in a green park with a fountain and an art garden featuring statues from all 21 APEC economies. Head up to the second level beneath the kite-shaped roof to catch the breeze off the Han River and snap a stunning panoramic shot of Dragon Bridge and Tran Thi Ly Bridge.', 'Mái vòm uốn lượn mang hình tượng ''Cánh diều bay cao'' bằng kết cấu thép khổng lồ rộng gần 800m2, công viên cây xanh, đài phun nước và vườn tượng nghệ thuật 21 nền kinh tế APEC.', 'A sweeping steel dome shaped like a "soaring kite," spanning nearly 800 square meters, set in a green park with a fountain and an art garden featuring statues from all 21 APEC economies.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/cong-vien-vuon-tuong-apec/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/cong-vien-vuon-tuong-apec/1.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('e5ef2f52-a9cd-4d7f-aa5d-8e3352211cd0', 'Cung Văn hóa Thiếu nhi Đà Nẵng', 'Da Nang Children''s Culture Palace', 'DN', 'Hải Châu', 'Số 02 Phan Đăng Lưu, P. Hòa Cường Bắc, Q. Hải Châu', 'Văn hóa', 'Văn hóa, Nghệ thuật, Sáng tạo', ARRAY['Văn hóa','Nghệ thuật','Sáng tạo']::text[], 1, 0, 45, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=Cung%20V%C4%83n%20h%C3%B3a%20Thi%E1%BA%BFu%20nhi%20%C4%90%C3%A0%20N%E1%BA%B5ng%2C%20H%E1%BA%A3i%20Ch%C3%A2u%2C%20%C4%90%C3%A0%20N%E1%BA%B5ng', '{"lat": 16.05, "lng": 108.221}'::jsonb, 'Công trình kiến trúc đạt giải thưởng quốc tế lấy cảm hứng từ trò chơi xếp hình học Tangram (hình con thú hình học đa diện) với các mảng màu sắc rực rỡ và hiện đại. Góc tường hoa văn động vật đa giác màu trắng, đỏ, vàng và khu công viên hoa anh đào là tọa độ chụp lookbook và ảnh phong cách năng động cực hot.', 'An internationally award-winning building inspired by the tangram puzzle, its facade made of polygonal animal shapes in bold, modern colors. The white, red, and yellow geometric animal-pattern walls and the cherry blossom garden nearby are a hot spot for lookbook shoots and dynamic, trendy photos.', 'Công trình kiến trúc đạt giải thưởng quốc tế lấy cảm hứng từ trò chơi xếp hình học Tangram (hình con thú hình học đa diện) với các mảng màu sắc rực rỡ và hiện đại.', 'An internationally award-winning building inspired by the tangram puzzle, its facade made of polygonal animal shapes in bold, modern colors.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/cung-van-hoa-thieu-nhi-da-nang/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/cung-van-hoa-thieu-nhi-da-nang/1.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('117f16bb-3732-4305-8855-a82171dd2af1', 'Danh thắng Ngũ Hành Sơn', 'Marble Mountains', 'DN', 'Ngũ Hành Sơn', '81 Huyền Trân Công Chúa, P. Hòa Hải, Q. Ngũ Hành Sơn', 'Di tích lịch sử', 'Lịch sử, Hoài cổ, Kiến trúc', ARRAY['Lịch sử','Hoài cổ','Kiến trúc']::text[], 1, 40000, 120, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=Danh%20th%E1%BA%AFng%20Ng%C5%A9%20H%C3%A0nh%20S%C6%A1n%2C%20Ng%C5%A9%20H%C3%A0nh%20S%C6%A1n%2C%20%C4%90%C3%A0%20N%E1%BA%B5ng', '{"lat": 16.0023, "lng": 108.2616}'::jsonb, 'Quần thể 5 ngọn núi đá vôi với hàng loạt hang động kỳ vĩ (Động Huyền Không, Động Âm Phủ, Động Vân Thông) và ngôi cổ tự Tam Thai, Linh Ứng. Động Huyền Không có lỗ thông thiên tuyệt đẹp; đến lúc 10:00 – 11:30 trưa khi ánh nắng rọi thẳng qua trần động tạo thành luồng sáng huyền ảo nhất.', 'A cluster of five limestone mountains riddled with spectacular caves (Huyen Khong Cave, Am Phu Cave, Van Thong Cave) and the ancient Tam Thai and Linh Ung pagodas. Huyen Khong Cave has a stunning skylight opening; visit between 10am and 11:30am, when sunlight beams straight down through the cave ceiling for the most magical light show.', 'Quần thể 5 ngọn núi đá vôi với hàng loạt hang động kỳ vĩ (Động Huyền Không, Động Âm Phủ, Động Vân Thông) và ngôi cổ tự Tam Thai, Linh Ứng.', 'A cluster of five limestone mountains riddled with spectacular caves (Huyen Khong Cave, Am Phu Cave, Van Thong Cave) and the ancient Tam Thai and Linh Ung pagodas.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/danh-thang-ngu-hanh-son/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/danh-thang-ngu-hanh-son/1.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('14626fcd-0541-4a51-aedf-55308418d3f2', 'Đèo Hải Vân & Di tích Hải Vân Quan', 'Hai Van Pass & Hai Van Quan Gate Relic', 'DN', 'Liên Chiểu', 'Quốc lộ 1A cũ, P. Hòa Hiệp Bắc, Q. Liên Chiểu', 'Thiên nhiên', 'Thiên nhiên, Hoang sơ, Thư giãn', ARRAY['Thiên nhiên','Hoang sơ','Thư giãn']::text[], 1, 0, 60, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=%C4%90%C3%A8o%20H%E1%BA%A3i%20V%C3%A2n%20%26%20Di%20t%C3%ADch%20H%E1%BA%A3i%20V%C3%A2n%20Quan%2C%20Li%C3%AAn%20Chi%E1%BB%83u%20%28gi%C3%A1p%20Ph%C3%BA%20L%E1%BB%99c%2C%20Hu%E1%BA%BF%29%2C%20%C4%90%C3%A0%20N%E1%BA%B5ng', '{"lat": 16.2021, "lng": 108.1265}'::jsonb, 'Cung đèo hiểm trở và ngoạn mục dài 21km ôm trọn dãy Bạch Mã đâm ngang ra biển Đông. Di tích cửa ải Hải Vân Quan thời Nguyễn ở độ cao 500m vừa được trùng tu nguyên bản. Dừng chân tại khúc cua tay áo chữ U hoặc các quán cà phê ngắm biển trên đỉnh đèo để săn biển mây bồng bềnh và ngắm trọn vịnh Lăng Cô lẫn vịnh Đà Nẵng.', 'A rugged, spectacular 21km mountain pass hugging the Bach Ma range as it juts out into the East Sea. The Nguyen-dynasty Hai Van Quan gate relic, at 500m elevation, has just been authentically restored. Stop at the hairpin U-turn or one of the sea-view cafes at the top of the pass to catch a sea of clouds and sweeping views over both Lang Co Bay and Da Nang Bay.', 'Cung đèo hiểm trở và ngoạn mục dài 21km ôm trọn dãy Bạch Mã đâm ngang ra biển Đông. Di tích cửa ải Hải Vân Quan thời Nguyễn ở độ cao 500m vừa được trùng tu nguyên bản.', 'A rugged, spectacular 21km mountain pass hugging the Bach Ma range as it juts out into the East Sea. The Nguyen-dynasty Hai Van Quan gate relic, at 500m elevation, has just been authentically restored.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/deo-hai-van-di-tich-hai-van-quan/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/deo-hai-van-di-tich-hai-van-quan/1.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('d0f0be79-2be0-4030-b442-35edfe1e84c3', 'Ghềnh Bàng', 'Ghenh Bang Reef', 'DN', 'Sơn Trà', 'Bán đảo Sơn Trà, P. Thọ Quang (cách Chùa Linh Ứng ~5km)', 'Thiên nhiên', 'Thiên nhiên, Hoang sơ, Thư giãn', ARRAY['Thiên nhiên','Hoang sơ','Thư giãn']::text[], 1, 0, 90, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=Gh%E1%BB%81nh%20B%C3%A0ng%2C%20S%C6%A1n%20Tr%C3%A0%2C%20%C4%90%C3%A0%20N%E1%BA%B5ng', '{"lat": 16.1215, "lng": 108.2866}'::jsonb, 'Dải bờ biển đá hoang sơ dài hơn 2km với hàng ngàn phiến đá nhấp nhô, nước biển xanh trong vắt thấy tận đáy và rạn san hô tự nhiên phong phú. Đoạn đường dốc bộ xuống bãi khá gồ ghề, bắt buộc mang giày có độ ma sát cao. Mang theo kính lặn, nước ngọt tráng người và đồ ăn nhẹ.', 'An unspoiled rocky coastline over 2km long, scattered with thousands of jagged rock formations, crystal-clear water you can see straight to the bottom, and rich natural coral reefs. The path down to the shore is steep and uneven, so wear shoes with good grip. Bring snorkeling goggles, fresh water to rinse off, and some snacks.', 'Dải bờ biển đá hoang sơ dài hơn 2km với hàng ngàn phiến đá nhấp nhô, nước biển xanh trong vắt thấy tận đáy và rạn san hô tự nhiên phong phú.', 'An unspoiled rocky coastline over 2km long, scattered with thousands of jagged rock formations, crystal-clear water you can see straight to the bottom, and rich natural coral reefs.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/ghenh-bang/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/ghenh-bang/1.jpg,https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/ghenh-bang/2.jpg,https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/ghenh-bang/3.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('4bfd2d9d-fbbd-47e4-b904-2fc413f8e551', 'Giếng Trời Đà Nẵng', 'Da Nang Sky Well', 'DN', 'Hòa Vang', 'Xã Hòa Ninh, H. Hòa Vang (Khu bảo tồn Bà Nà - Núi Chúa)', 'Thiên nhiên', 'Thiên nhiên, Hoang sơ, Thư giãn', ARRAY['Thiên nhiên','Hoang sơ','Thư giãn']::text[], 1, 0, 90, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=Gi%E1%BA%BFng%20Tr%E1%BB%9Di%20%C4%90%C3%A0%20N%E1%BA%B5ng%2C%20H%C3%B2a%20Vang%2C%20%C4%90%C3%A0%20N%E1%BA%B5ng', '{"lat": 16.01, "lng": 108.01}'::jsonb, 'Thác nước khổng lồ đổ thẳng từ độ cao hơn 25m xuống một hồ nước tự nhiên sâu và xanh ngắt màu ngọc bích nằm lọt thỏm giữa hẻm đá rừng già. Trekking đường rừng dài hơn 10km cần có thể lực tốt, đi theo nhóm có người dẫn đường, mang giày bám đá, áo phao và thuốc chống vắt muỗi.', 'A massive waterfall plunges straight down more than 25m into a deep, jade-green natural pool tucked inside a rocky gorge in the old-growth forest. The trek in is over 10km through the forest and requires good stamina; go with a group and a guide, and bring grippy shoes, a life vest, and leech and mosquito repellent.', 'Thác nước khổng lồ đổ thẳng từ độ cao hơn 25m xuống một hồ nước tự nhiên sâu và xanh ngắt màu ngọc bích nằm lọt thỏm giữa hẻm đá rừng già.', 'A massive waterfall plunges straight down more than 25m into a deep, jade-green natural pool tucked inside a rocky gorge in the old-growth forest.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/gieng-troi-da-nang/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/gieng-troi-da-nang/1.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('54f0d61b-9607-4f72-a2d3-750c271f0fcb', 'Hải đăng Tiên Sa', 'Tien Sa Lighthouse', 'DN', 'Sơn Trà', 'Đỉnh bán đảo Sơn Trà, P. Thọ Quang, Q. Sơn Trà', 'Thiên nhiên', 'Thiên nhiên, Hoang sơ, Thư giãn', ARRAY['Thiên nhiên','Hoang sơ','Thư giãn']::text[], 1, 20000, 60, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=H%E1%BA%A3i%20%C4%91%C4%83ng%20Ti%C3%AAn%20Sa%2C%20S%C6%A1n%20Tr%C3%A0%2C%20%C4%90%C3%A0%20N%E1%BA%B5ng', '{"lat": 16.1253, "lng": 108.2904}'::jsonb, 'Ngọn hải đăng cổ kính được người Pháp xây dựng vào năm 1902 cao 15.6m, mang tông màu vàng cổ điển nổi bật giữa nền xanh ngắt của rừng biển. Tòa tháp và ban công hải đăng là góc chụp ảnh phong cách retro châu Âu tuyệt đẹp nhìn thẳng ra biển Đông bao la.', 'A historic lighthouse built by the French in 1902, standing 15.6m tall in a classic yellow that stands out against the deep green of the coastal forest. The tower and its balcony make a gorgeous retro-European photo spot, looking straight out over the vast East Sea.', 'Ngọn hải đăng cổ kính được người Pháp xây dựng vào năm 1902 cao 15.6m, mang tông màu vàng cổ điển nổi bật giữa nền xanh ngắt của rừng biển.', 'A historic lighthouse built by the French in 1902, standing 15.6m tall in a classic yellow that stands out against the deep green of the coastal forest.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/hai-dang-tien-sa/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/hai-dang-tien-sa/1.jpg,https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/hai-dang-tien-sa/2.jpg,https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/hai-dang-tien-sa/3.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('dafa5bca-055f-48e5-8fc5-72cedeb3c92d', 'Mũi Nghê Sơn Trà', 'Nghe Cape, Son Tra', 'DN', 'Sơn Trà', 'Phía Đông Nam bán đảo Sơn Trà, P. Thọ Quang', 'Thiên nhiên', 'Thiên nhiên, Hoang sơ, Thư giãn', ARRAY['Thiên nhiên','Hoang sơ','Thư giãn']::text[], 1, 0, 60, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=M%C5%A9i%20Ngh%C3%AA%20S%C6%A1n%20Tr%C3%A0%2C%20S%C6%A1n%20Tr%C3%A0%2C%20%C4%90%C3%A0%20N%E1%BA%B5ng', '{"lat": 16.098, "lng": 108.295}'::jsonb, 'Tọa độ đón những tia nắng bình minh đầu tiên của thành phố Đà Nẵng. Khối đá tự nhiên hình dáng con sư tử biển khổng lồ chầu ra biển với hồ nước biển vô cực tự nhiên. Trekking xuống Mũi Nghê cần có người dẫn đường hoặc theo nhóm vì đường rừng dốc và sóng đập mạnh, không tắm khi biển động.', 'The spot where Da Nang catches its very first rays of dawn. A natural rock formation shaped like a giant sea lion faces the ocean, beside a natural infinity pool carved by the sea. Hiking down to Nghe Cape requires a guide or a group, since the forest trail is steep and the waves can be strong; don''t swim when the sea is rough.', 'Tọa độ đón những tia nắng bình minh đầu tiên của thành phố Đà Nẵng. Khối đá tự nhiên hình dáng con sư tử biển khổng lồ chầu ra biển với hồ nước biển vô cực tự nhiên.', 'The spot where Da Nang catches its very first rays of dawn. A natural rock formation shaped like a giant sea lion faces the ocean, beside a natural infinity pool carved by the sea.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/mui-nghe-son-tra/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/mui-nghe-son-tra/1.jpg,https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/mui-nghe-son-tra/2.jpg,https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/mui-nghe-son-tra/3.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('76d14a37-476d-4821-b161-a7767555e5b2', 'Nhà thờ Chính Tòa Đà Nẵng', 'Da Nang Cathedral', 'DN', 'Hải Châu', '156 Trần Phú, P. Hải Châu 1, Q. Hải Châu', 'Di tích tín ngưỡng', 'Tâm linh, Kiến trúc, Yên tĩnh', ARRAY['Tâm linh','Kiến trúc','Yên tĩnh']::text[], 1, 0, 20, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=Nh%C3%A0%20th%E1%BB%9D%20Ch%C3%ADnh%20T%C3%B2a%20%C4%90%C3%A0%20N%E1%BA%B5ng%2C%20H%E1%BA%A3i%20Ch%C3%A2u%2C%20%C4%90%C3%A0%20N%E1%BA%B5ng', '{"lat": 16.0696, "lng": 108.2216}'::jsonb, 'Xây dựng năm 1923 thời Pháp thuộc theo phong cách Gothic với các vòm cửa nhọn và tháp chuông cao 70m có tượng con gà bằng hợp kim trên đỉnh mang ý nghĩa thức tỉnh tín đồ. Toàn bộ nhà thờ sơn màu hồng phấn pastel cực kỳ ngọt ngào, là góc chụp hình check-in triệu like nằm ngay trung tâm thành phố.', 'Built in 1923 during French colonial rule in Gothic style, with pointed arches and a 70m bell tower topped by an alloy rooster symbolizing the call to awaken the faithful. The entire church is painted in a sweet pastel pink, making it a hugely popular photo spot right in the city center.', 'Xây dựng năm 1923 thời Pháp thuộc theo phong cách Gothic với các vòm cửa nhọn và tháp chuông cao 70m có tượng con gà bằng hợp kim trên đỉnh mang ý nghĩa thức tỉnh tín đồ.', 'Built in 1923 during French colonial rule in Gothic style, with pointed arches and a 70m bell tower topped by an alloy rooster symbolizing the call to awaken the faithful.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/nha-tho-chinh-toa-da-nang/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/nha-tho-chinh-toa-da-nang/1.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('714ea47d-a961-42d3-9927-3102d3921f17', 'Suối khoáng nóng Núi Thần Tài', 'Nui Than Tai Hot Springs', 'DN', 'Hòa Vang', 'Thôn Phú Túc, Xã Hòa Phú, Huyện Hòa Vang', 'Du lịch sinh thái', 'Thiên nhiên, Thư giãn, Gia đình', ARRAY['Thiên nhiên','Thư giãn','Gia đình']::text[], 3, 450000, 180, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=Su%E1%BB%91i%20kho%C3%A1ng%20n%C3%B3ng%20N%C3%BAi%20Th%E1%BA%A7n%20T%C3%A0i%2C%20H%C3%B2a%20Vang%2C%20%C4%90%C3%A0%20N%E1%BA%B5ng', '{"lat": 15.97, "lng": 108.045}'::jsonb, 'Công viên suối khoáng nóng tự nhiên giữa thung lũng núi Chúa với hồ tắm khoáng Onsen chuẩn Nhật Bản, công viên nước trên núi, tắm bùn khoáng và luộc trứng trường thọ. Thử trải nghiệm tắm khoáng nóng thư giãn cơ bắp sau đó ăn trứng gà luộc chín từ mỏ khoáng nóng thiên nhiên 75 độ C cực kỳ bổ dưỡng.', 'A natural hot mineral spring park in the Nui Chua valley, with Japanese-style onsen mineral pools, a mountain water park, mineral mud baths, and "longevity" eggs boiled on-site. Try a relaxing mineral soak to ease your muscles, then eat an egg boiled right in the natural 75-degree-Celsius hot spring, wonderfully nourishing.', 'Công viên suối khoáng nóng tự nhiên giữa thung lũng núi Chúa với hồ tắm khoáng Onsen chuẩn Nhật Bản, công viên nước trên núi, tắm bùn khoáng và luộc trứng trường thọ.', 'A natural hot mineral spring park in the Nui Chua valley, with Japanese-style onsen mineral pools, a mountain water park, mineral mud baths, and "longevity" eggs boiled on-site.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/suoi-khoang-nong-nui-than-tai/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/suoi-khoang-nong-nui-than-tai/1.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('0a644dc5-1667-4d36-83a1-eccb57674598', 'Suối Mơ Đà Nẵng', 'Dream Stream, Da Nang', 'DN', 'Hòa Vang', 'Xã Hòa Ninh, Huyện Hòa Vang (dưới chân núi Bà Nà)', 'Thiên nhiên', 'Thiên nhiên, Hoang sơ, Thư giãn', ARRAY['Thiên nhiên','Hoang sơ','Thư giãn']::text[], 2, 70000, 120, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=Su%E1%BB%91i%20M%C6%A1%20%C4%90%C3%A0%20N%E1%BA%B5ng%2C%20H%C3%B2a%20Vang%2C%20%C4%90%C3%A0%20N%E1%BA%B5ng', '{"lat": 15.995, "lng": 108.015}'::jsonb, 'Con suối mát lạnh bắt nguồn từ mạch ngầm đỉnh núi Bà Nà đổ về thung lũng, tạo nên những thác nước nhỏ và hồ tắm thiên nhiên trong veo rợp bóng cây cổ thụ. Thuê các chòi tre ven bờ suối để vừa nghe tiếng nước chảy róc rách vừa thưởng thức món gà đồi nướng mọi chấm muối ớt chanh chuẩn vị.', 'A cool stream fed by underground springs at the top of Ba Na Mountain, flowing down into the valley to form small waterfalls and clear natural swimming pools shaded by ancient trees. Rent a bamboo hut by the stream to listen to the babbling water while enjoying grilled hill chicken dipped in salt, chili, and lime, done just right.', 'Con suối mát lạnh bắt nguồn từ mạch ngầm đỉnh núi Bà Nà đổ về thung lũng, tạo nên những thác nước nhỏ và hồ tắm thiên nhiên trong veo rợp bóng cây cổ thụ.', 'A cool stream fed by underground springs at the top of Ba Na Mountain, flowing down into the valley to form small waterfalls and clear natural swimming pools shaded by ancient trees.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/suoi-mo-da-nang/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/DN/suoi-mo-da-nang/1.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('822e3be4-534c-4598-84a3-172868c5e486', 'Bảo tàng Mỹ thuật TP. Hồ Chí Minh', 'Ho Chi Minh City Fine Arts Museum', 'SG', 'Quận 1', '97A Phó Đức Chính, P. Nguyễn Thái Bình, Quận 1', 'Bảo tàng', 'Lịch sử, Giáo dục, Kiến trúc', ARRAY['Lịch sử','Giáo dục','Kiến trúc']::text[], 1, 30000, 60, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=B%E1%BA%A3o%20t%C3%A0ng%20M%E1%BB%B9%20thu%E1%BA%ADt%20TP.%20H%E1%BB%93%20Ch%C3%AD%20Minh%2C%20Qu%E1%BA%ADn%201%2C%20TP.%20H%E1%BB%93%20Ch%C3%AD%20Minh', '{"lat": 10.7698, "lng": 106.6946}'::jsonb, 'Tòa biệt thự tráng lệ từng thuộc đại hào phú Hứa Bổn Hòa (Chú Hỏa) kết hợp phong cách kiến trúc Art Deco và Baroque châu Âu. Nổi bật với thang máy cổ bằng gỗ bọc đồng đầu tiên ở Sài Gòn, các ô cửa sổ kính màu rực rỡ, hành lang lát gạch bông và bộ sưu tập mỹ thuật vô giá. Điểm chụp ảnh nghệ thuật lookbook hàng đầu. Chọn góc cầu thang xoắn ốc và hành lang kính màu đón ánh nắng xiên buổi sáng để có những bức ảnh lung linh.', 'A magnificent mansion once owned by the wealthy tycoon Hua Bon Hoa (known as "Uncle Hoa"), blending Art Deco with European Baroque style. It''s known for Saigon''s first wood-paneled, copper-clad elevator, vividly colored stained-glass windows, patterned tile corridors, and a priceless art collection. A top spot for artistic lookbook photos. Pick the spiral staircase or the stained-glass corridor in the morning light for the most stunning shots.', 'Tòa biệt thự tráng lệ từng thuộc đại hào phú Hứa Bổn Hòa (Chú Hỏa) kết hợp phong cách kiến trúc Art Deco và Baroque châu Âu. Nổi bật với thang máy cổ bằng gỗ bọc đồng đầu tiên ở Sài Gòn, các ô cửa sổ kính màu rực rỡ, hàn', 'A magnificent mansion once owned by the wealthy tycoon Hua Bon Hoa (known as "Uncle Hoa"), blending Art Deco with European Baroque style.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/bao-tang-my-thuat-tp-ho-chi-minh/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/bao-tang-my-thuat-tp-ho-chi-minh/1.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('a604ff6f-a611-4561-822b-c960ac33c0ff', 'Bảo tàng Thành phố Hồ Chí Minh', 'Ho Chi Minh City Museum', 'SG', 'Quận 1', '65 Lý Tự Trọng, P. Bến Nghé, Quận 1', 'Bảo tàng', 'Lịch sử, Giáo dục, Kiến trúc', ARRAY['Lịch sử','Giáo dục','Kiến trúc']::text[], 1, 30000, 60, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=B%E1%BA%A3o%20t%C3%A0ng%20Th%C3%A0nh%20ph%E1%BB%91%20H%E1%BB%93%20Ch%C3%AD%20Minh%2C%20Qu%E1%BA%ADn%201%2C%20TP.%20H%E1%BB%93%20Ch%C3%AD%20Minh', '{"lat": 10.7775, "lng": 106.6998}'::jsonb, 'Tòa dinh thự cổ phong cách Tân cổ điển Pháp (Neoclassical) do KTS Foulhoux thiết kế năm 1885 với hàng cột Corinth đồ sộ, cầu thang gỗ uốn lượn uy nghi và hệ thống đường hầm ngầm bí mật kết nối tới Dinh Độc Lập. Trưng bày lịch sử hơn 300 năm hình thành Sài Gòn. Cầu thang gỗ uốn lượn tại đại sảnh và hành lang dài đón gió là điểm chụp ảnh áo dài cưới và lookbook cổ điển đẹp bậc nhất thành phố.', 'An old French Neoclassical mansion designed by architect Foulhoux in 1885, with grand Corinthian columns, a majestic curving wooden staircase, and a secret underground tunnel system connecting to the Reunification Palace. It showcases more than 300 years of Saigon''s history. The curving wooden staircase in the main hall and the long, breezy corridor are among the city''s best spots for wedding áo dài and classic lookbook photos.', 'Tòa dinh thự cổ phong cách Tân cổ điển Pháp (Neoclassical) do KTS Foulhoux thiết kế năm 1885 với hàng cột Corinth đồ sộ, cầu thang gỗ uốn lượn uy nghi và hệ thống đường hầm ngầm bí mật kết nối tới Dinh Độc Lập. Trưng bày', 'An old French Neoclassical mansion designed by architect Foulhoux in 1885, with grand Corinthian columns, a majestic curving wooden staircase, and a secret underground tunnel system connecting to the Reunification Palace.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/bao-tang-thanh-pho-ho-chi-minh/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/bao-tang-thanh-pho-ho-chi-minh/1.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('edc43fb8-3c37-4cd7-b8c9-5f636c138cf1', 'Bến Bạch Đằng & Tuyến Buýt sông Sài Gòn', 'Bach Dang Wharf & Saigon River Waterbus', 'SG', 'Quận 1', 'Số 10B Tôn Đức Thắng, P. Bến Nghé, Quận 1', 'Trải nghiệm', 'Check-in, Về đêm, Nhộn nhịp', ARRAY['Check-in','Về đêm','Nhộn nhịp']::text[], 1, 15000, 60, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=B%E1%BA%BFn%20B%E1%BA%A1ch%20%C4%90%E1%BA%B1ng%20%26%20Tuy%E1%BA%BFn%20Bu%C3%BDt%20s%C3%B4ng%20S%C3%A0i%20G%C3%B2n%2C%20Qu%E1%BA%ADn%201%2C%20TP.%20H%E1%BB%93%20Ch%C3%AD%20Minh', '{"lat": 10.7779, "lng": 106.7057}'::jsonb, 'Công viên bến tàu hiện đại với quảng trường lát đá, đài sen biểu tượng và bến xuất phát tuyến Waterbus dọc sông Sài Gòn từ Q1 qua Bình Thạnh đến TP. Thủ Đức (Linh Đông). Trải nghiệm ngắm trọn các tòa cao ốc Landmark 81, Bitexco và cầu Ba Son từ mặt sông mát rượi. Nên đặt vé trực tuyến trước vào chuyến 16:30 - 17:30 để đón khoảnh khắc hoàng hôn buông trên sông và ngắm các tòa nhà chọc trời bừng sáng đèn.', 'A modern riverside park with a stone-paved plaza, an iconic lotus-shaped tower, and the starting pier for the Waterbus route along the Saigon River, running from District 1 through Binh Thanh to Thu Duc City (Linh Dong). Take in full views of Landmark 81, Bitexco, and Ba Son Bridge from the cool river breeze. Book online ahead for the 4:30-5:30pm trip to catch sunset falling over the river and the skyscrapers lighting up.', 'Công viên bến tàu hiện đại với quảng trường lát đá, đài sen biểu tượng và bến xuất phát tuyến Waterbus dọc sông Sài Gòn từ Q1 qua Bình Thạnh đến TP. Thủ Đức (Linh Đông). Trải nghiệm ngắm trọn các tòa cao ốc Landmark 81, ', 'A modern riverside park with a stone-paved plaza, an iconic lotus-shaped tower, and the starting pier for the Waterbus route along the Saigon River, running from District 1 through Binh Thanh to Thu Duc City (Linh Dong).', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/ben-bach-dang-tuyen-buyt-song-sai-gon/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/ben-bach-dang-tuyen-buyt-song-sai-gon/1.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('99d15bcb-876d-494a-bef9-7a3e1d15b6e5', 'Bến Nhà Rồng - Bảo tàng Hồ Chí Minh', 'Nha Rong Wharf - Ho Chi Minh Museum', 'SG', 'Quận 4', 'Số 01 Nguyễn Tất Thành, P. 12, Quận 4', 'Bảo tàng', 'Lịch sử, Giáo dục, Kiến trúc', ARRAY['Lịch sử','Giáo dục','Kiến trúc']::text[], 1, 30000, 60, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=B%E1%BA%BFn%20Nh%C3%A0%20R%E1%BB%93ng%20-%20B%E1%BA%A3o%20t%C3%A0ng%20H%E1%BB%93%20Ch%C3%AD%20Minh%2C%20Qu%E1%BA%ADn%204%2C%20TP.%20H%E1%BB%93%20Ch%C3%AD%20Minh', '{"lat": 10.7693, "lng": 106.7049}'::jsonb, 'Nguyên là trụ sở hãng vận tải đường biển Messageries Maritimes xây dựng năm 1863 mang kiến trúc Pháp với đôi rồng ngậm trăng bằng đất nung trên nóc. Nơi người thanh niên Nguyễn Tất Thành ra đi tìm đường cứu nước ngày 5/6/1911 trên con tàu Amiral Latouche-Tréville. Khuôn viên hoa viên ven sông có tầm nhìn triệu đô phóng thẳng ra sông Sài Gòn, cầu Ba Son và bến Bạch Đằng lung linh lộng gió.', 'Originally the headquarters of the Messageries Maritimes shipping company, built in 1863 in French architectural style, topped with a pair of terracotta dragons holding the moon in their mouths. This is where the young Nguyen Tat Thanh departed on June 5, 1911, aboard the ship Amiral Latouche-Tréville in search of a way to save his country. The riverside garden grounds offer a million-dollar view straight out over the Saigon River, Ba Son Bridge, and the breezy, glittering Bach Dang Wharf.', 'Nguyên là trụ sở hãng vận tải đường biển Messageries Maritimes xây dựng năm 1863 mang kiến trúc Pháp với đôi rồng ngậm trăng bằng đất nung trên nóc. Nơi người thanh niên Nguyễn Tất Thành ra đi tìm đường cứu nước ngày 5/6', 'Originally the headquarters of the Messageries Maritimes shipping company, built in 1863 in French architectural style, topped with a pair of terracotta dragons holding the moon in their mouths.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/ben-nha-rong-bao-tang-ho-chi-minh/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/ben-nha-rong-bao-tang-ho-chi-minh/1.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('217f3ea7-c6a8-4675-809b-0d6e7cb88ce7', 'Cầu Ánh Sao & Hồ Bán Nguyệt', 'Star Light Bridge & Crescent Lake', 'SG', 'Quận 7', 'Khu đô thị Phú Mỹ Hưng, đường Tôn Dật Tiên, P. Tân Phú, Quận 7', 'Trải nghiệm', 'Check-in, Về đêm, Nhộn nhịp', ARRAY['Check-in','Về đêm','Nhộn nhịp']::text[], 1, 0, 45, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=C%E1%BA%A7u%20%C3%81nh%20Sao%20%26%20H%E1%BB%93%20B%C3%A1n%20Nguy%E1%BB%87t%2C%20Qu%E1%BA%ADn%207%2C%20TP.%20H%E1%BB%93%20Ch%C3%AD%20Minh', '{"lat": 10.729, "lng": 106.7205}'::jsonb, 'Cầu bộ hành uốn cong hình mặt trăng dài 170m bắc qua kênh Thầy Tiêu nối Hồ Bán Nguyệt với khu Kênh Đào. Trang bị hệ thống phun nước và đèn LED 7 màu đổi sắc liên tục cùng hàng ngàn mắt đèn sáng rực trên mặt cầu như dải ngân hà đầy sao. Dọc theo bờ Hồ Bán Nguyệt có các cung đường dạo bộ xanh mát lát đá và chuỗi nhà hàng, quán cà phê ven hồ lãng mạn cho các cặp đôi hẹn hò.', 'A curved, moon-shaped pedestrian bridge 170m long, spanning Thay Tieu Canal to connect Crescent Lake with the Canal District. It''s fitted with fountains and color-shifting 7-color LED lights, with thousands of lights twinkling across the bridge deck like a starry galaxy. Along the shores of Crescent Lake are shaded, paved walking paths and a string of romantic lakeside restaurants and cafes, perfect for couples on a date.', 'Cầu bộ hành uốn cong hình mặt trăng dài 170m bắc qua kênh Thầy Tiêu nối Hồ Bán Nguyệt với khu Kênh Đào. Trang bị hệ thống phun nước và đèn LED 7 màu đổi sắc liên tục cùng hàng ngàn mắt đèn sáng rực trên mặt cầu như dải n', 'A curved, moon-shaped pedestrian bridge 170m long, spanning Thay Tieu Canal to connect Crescent Lake with the Canal District.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/cau-anh-sao-ho-ban-nguyet/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/cau-anh-sao-ho-ban-nguyet/1.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('c0f2aa2b-40cf-402c-b5a4-685bd0515823', 'Cầu Ba Son', 'Ba Son Bridge', 'SG', 'Quận 1', 'Nối đường Tôn Đức Thắng (Q1) với đại lộ Mai Chí Thọ (KĐT Thủ Thiêm)', 'Trải nghiệm', 'Check-in, Về đêm, Nhộn nhịp', ARRAY['Check-in','Về đêm','Nhộn nhịp']::text[], 1, 0, 20, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=C%E1%BA%A7u%20Ba%20Son%2C%20Qu%E1%BA%ADn%201%20%26%20TP.%20Th%E1%BB%A7%20%C4%90%E1%BB%A9c%2C%20TP.%20H%E1%BB%93%20Ch%C3%AD%20Minh', '{"lat": 10.7838, "lng": 106.7128}'::jsonb, 'Cây cầu dây văng bất đối xứng dài 1.465m với trụ tháp chính hình vòm cao 113m nghiêng về phía Thủ Thiêm như cánh buồm căng gió. Về đêm cầu được chiếu sáng nghệ thuật lung linh, mở ra góc nhìn toàn cảnh skyline trung tâm Quận 1 ngoạn mục nhất. Chân cầu phía bờ Thủ Thiêm là tụ điểm chill nổi tiếng của giới trẻ với bãi cỏ rộng rãi, xe trà chanh dạo mát và góc chụp toàn cảnh skyline Quận 1 triệu đô.', 'An asymmetric cable-stayed bridge 1,465m long, with a 113m-tall arched main pylon leaning toward Thu Thiem like a wind-filled sail. At night the bridge is lit up with dazzling artistic lighting, opening up the most spectacular panoramic view of the District 1 skyline. The Thu Thiem side of the bridge is a famous hangout for young people, with wide lawns, roving iced-tea carts, and a million-dollar skyline photo spot.', 'Cây cầu dây văng bất đối xứng dài 1.465m với trụ tháp chính hình vòm cao 113m nghiêng về phía Thủ Thiêm như cánh buồm căng gió. Về đêm cầu được chiếu sáng nghệ thuật lung linh, mở ra góc nhìn toàn cảnh skyline trung tâm ', 'An asymmetric cable-stayed bridge 1,465m long, with a 113m-tall arched main pylon leaning toward Thu Thiem like a wind-filled sail.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/cau-ba-son/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/cau-ba-son/1.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('99f29822-bcda-41b1-b5b3-141b6190ec4a', 'Chợ Bình Tây', 'Binh Tay Market', 'SG', 'Quận 6', '57A Tháp Mười, P. 2, Quận 6', 'Trải nghiệm', 'Check-in, Về đêm, Nhộn nhịp', ARRAY['Check-in','Về đêm','Nhộn nhịp']::text[], 1, 0, 60, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=Ch%E1%BB%A3%20B%C3%ACnh%20T%C3%A2y%2C%20Qu%E1%BA%ADn%206%2C%20TP.%20H%E1%BB%93%20Ch%C3%AD%20Minh', '{"lat": 10.7496, "lng": 106.6513}'::jsonb, 'Xây dựng năm 1928 do thương gia người Hoa Quách Đàm hiến tặng đất và tài trợ. Kiến trúc Á - Đông đặc trưng với mái ngói chồng lớp kiểu vảy cá, tháp chuông trung tâm bát giác và hoa viên lộ thiên chính giữa đặt tượng cụ Quách Đàm. Trung tâm bán buôn (sỉ) lớn nhất miền Nam. Bạn có thể mua đặc sản hạt sen sấy, mứt gừng, khô bò, gia vị thuốc bắc với giá sỉ cực tốt tại tầng trệt.', 'Built in 1928, with the land donated and construction funded by Chinese merchant Quach Dam. Its distinctive East Asian architecture features fish-scale layered roof tiles, an octagonal central bell tower, and an open-air central garden with a statue of Quach Dam himself. It''s the largest wholesale trading hub in southern Vietnam. On the ground floor you can buy specialty dried lotus seeds, candied ginger, dried beef, and Chinese herbal spices at excellent wholesale prices.', 'Xây dựng năm 1928 do thương gia người Hoa Quách Đàm hiến tặng đất và tài trợ. Kiến trúc Á - Đông đặc trưng với mái ngói chồng lớp kiểu vảy cá, tháp chuông trung tâm bát giác và hoa viên lộ thiên chính giữa đặt tượng cụ Q', 'Built in 1928, with the land donated and construction funded by Chinese merchant Quach Dam.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/cho-binh-tay/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/cho-binh-tay/1.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('1feb5494-ad79-405e-a5cc-fff6014cc3e3', 'Hội quán Nghĩa An', 'Nghia An Assembly Hall', 'SG', 'Quận 5', '678 Nguyễn Trãi, P. 11, Quận 5', 'Di tích tín ngưỡng', 'Tâm linh, Kiến trúc, Yên tĩnh', ARRAY['Tâm linh','Kiến trúc','Yên tĩnh']::text[], 1, 0, 30, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=H%E1%BB%99i%20qu%C3%A1n%20Ngh%C4%A9a%20An%2C%20Qu%E1%BA%ADn%205%2C%20TP.%20H%E1%BB%93%20Ch%C3%AD%20Minh', '{"lat": 10.7536, "lng": 106.6629}'::jsonb, 'Công trình kiến trúc đặc trưng của người Hoa Triều Châu xây dựng từ thế kỷ 19 thờ Quan Thánh Đế Quân. Nổi tiếng với nghệ thuật chạm khắc gỗ sơn son thếp vàng tinh xảo ở các bao lam, hoành phi, tượng ngựa Xích Thỏ bằng gỗ kích thước lớn và sân đình rộng rãi. Tục lệ chui qua bụng ngựa Xích Thỏ và rung chuông đồng dưới cổ ngựa để cầu sức khỏe dồi dào, xua tan vận rủi và công việc làm ăn hanh thông.', 'A distinctive piece of Teochew Chinese architecture built in the 19th century, dedicated to Lord Guan (Quan Thanh De Quan). It''s famous for its exquisite red-and-gold lacquered woodcarvings on altar screens and panels, a large wooden statue of the horse Red Hare, and a spacious courtyard. A local custom is to crawl under the belly of the Red Hare statue and ring the bronze bell beneath its neck, to pray for good health, ward off bad luck, and ensure smooth business.', 'Công trình kiến trúc đặc trưng của người Hoa Triều Châu xây dựng từ thế kỷ 19 thờ Quan Thánh Đế Quân. Nổi tiếng với nghệ thuật chạm khắc gỗ sơn son thếp vàng tinh xảo ở các bao lam, hoành phi, tượng ngựa Xích Thỏ bằng gỗ', 'A distinctive piece of Teochew Chinese architecture built in the 19th century, dedicated to Lord Guan (Quan Thanh De Quan).', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/hoi-quan-nghia-an/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/hoi-quan-nghia-an/1.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('39b0c544-f2b5-4335-a316-00ff035619c7', 'Chợ hoa đêm & Phố ẩm thực Hồ Thị Kỷ', 'Ho Thi Ky Night Flower Market & Food Street', 'SG', 'Quận 10', 'Hẻm 52 Hồ Thị Kỷ, P. 1, Quận 10', 'Ẩm thực', 'Ẩm thực, Về đêm, Nhộn nhịp', ARRAY['Ẩm thực','Về đêm','Nhộn nhịp']::text[], 1, 0, 90, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=Ch%E1%BB%A3%20hoa%20%C4%91%C3%AAm%20%26%20Ph%E1%BB%91%20%E1%BA%A9m%20th%E1%BB%B1c%20H%E1%BB%93%20Th%E1%BB%8B%20K%E1%BB%B7%2C%20Qu%E1%BA%ADn%2010%2C%20TP.%20H%E1%BB%93%20Ch%C3%AD%20Minh', '{"lat": 10.7659, "lng": 106.6704}'::jsonb, 'Chợ đầu mối hoa tươi lớn nhất Sài Gòn hoạt động thâu đêm quy tụ muôn ngàn loài hoa Đà Lạt và miền Tây; kết hợp phố ẩm thực nức tiếng với hàng trăm món ăn vặt Campuchia - Việt Nam: chè Campuchia cô Có, bún Num-bo-chóc, bánh tráng nướng, trà đào dầm. Gửi xe ở đầu hẻm đường Lý Thái Tổ rồi đi bộ vào. Chỉ cần khoảng 100.000 - 150.000 VNĐ là bạn có thể thưởng thức no nê hàng chục món ăn đường phố hấp dẫn.', 'Saigon''s biggest wholesale fresh-flower market, running all night and gathering countless flower varieties from Da Lat and the Mekong Delta; paired with a famous food street serving hundreds of Cambodian-Vietnamese snacks: Co Co''s Cambodian che, num-bo-chóc noodles, grilled rice paper, and peach tea. Park your bike at the alley entrance on Ly Thai To Street and walk in from there. With just 100,000-150,000 VND you can eat your fill of dozens of tempting street food dishes.', 'Chợ đầu mối hoa tươi lớn nhất Sài Gòn hoạt động thâu đêm quy tụ muôn ngàn loài hoa Đà Lạt và miền Tây; kết hợp phố ẩm thực nức tiếng với hàng trăm món ăn vặt Campuchia - Việt Nam: chè Campuchia cô Có, bún Num-bo-chóc, bá', 'Saigon''s biggest wholesale fresh-flower market, running all night and gathering countless flower varieties from Da Lat and the Mekong Delta, paired with a famous food street serving hundreds of Cambodian-Vietnamese snacks.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/cho-hoa-dem-pho-am-thuc-ho-thi-ky/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/cho-hoa-dem-pho-am-thuc-ho-thi-ky/1.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('cc520cca-2d27-48b0-9035-b9fdd866bbe6', 'Chợ Tân Định', 'Tan Dinh Market', 'SG', 'Quận 1', '336 Hai Bà Trưng, P. Tân Định, Quận 1', 'Trải nghiệm', 'Check-in, Về đêm, Nhộn nhịp', ARRAY['Check-in','Về đêm','Nhộn nhịp']::text[], 1, 0, 60, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=Ch%E1%BB%A3%20T%C3%A2n%20%C4%90%E1%BB%8Bnh%2C%20Qu%E1%BA%ADn%201%2C%20TP.%20H%E1%BB%93%20Ch%C3%AD%20Minh', '{"lat": 10.7902, "lng": 106.691}'::jsonb, 'Ngôi chợ cổ xây dựng năm 1926 với mặt tiền 3 tháp chuông kiểu Pháp cổ kính. Nổi danh là ''chợ nhà giàu'' với các sạp bán vải vóc lụa là cao cấp và khu ẩm thực đêm nức tiếng: cháo sườn bà Hào, xôi gà Tân Định da giòn lòng đào trứng non, chè trang thơm ngọt. Sau khi dạo phố, hãy ghé qua chợ Tân Định thưởng thức đĩa xôi gà xé lòng đào trứng non hoặc tô cháo sườn sụn nóng hổi trứ danh.', 'An old market built in 1926, with a classic French-style facade topped by three bell towers. Known as the "rich people''s market" for its stalls of high-end silk and fabric, plus a famous night food scene: Mrs. Hao''s pork rib porridge, Tan Dinh''s crispy-skinned chicken sticky rice with soft-boiled egg yolk, and sweet, fragrant che trang. After strolling the streets, stop by Tan Dinh Market for a plate of shredded chicken sticky rice with soft egg yolk, or the famous steaming-hot cartilage rib porridge.', 'Ngôi chợ cổ xây dựng năm 1926 với mặt tiền 3 tháp chuông kiểu Pháp cổ kính. Nổi danh là ''chợ nhà giàu'' với các sạp bán vải vóc lụa là cao cấp và khu ẩm thực đêm nức tiếng: cháo sườn bà Hào, xôi gà Tân Định da giòn lòng đ', 'An old market built in 1926, with a classic French-style facade topped by three bell towers.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/cho-tan-dinh/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/cho-tan-dinh/1.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('c9c66274-c7c5-4882-b2bf-b8b10baba1c2', 'Chùa Giác Lâm', 'Giac Lam Pagoda', 'SG', 'Tân Bình', '565 Lạc Long Quân, P. 10, Q. Tân Bình', 'Di tích tín ngưỡng', 'Tâm linh, Kiến trúc, Yên tĩnh', ARRAY['Tâm linh','Kiến trúc','Yên tĩnh']::text[], 1, 0, 30, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=Ch%C3%B9a%20Gi%C3%A1c%20L%C3%A2m%2C%20T%C3%A2n%20B%C3%ACnh%2C%20TP.%20H%E1%BB%93%20Ch%C3%AD%20Minh', '{"lat": 10.7658, "lng": 106.6389}'::jsonb, 'Tổ đình Phật giáo cổ kính nhất đất Gia Định xây dựng năm 1744 với kiến trúc chữ ''Tam'' kiểu nhà rường Nam Bộ gồm 98 cột gỗ quý khắc chữ Hán chìm. Lưu giữ 113 pho tượng cổ bằng gỗ mít và bộ bao lam chạm cửu long tuyệt mỹ trên 200 năm tuổi. Bảo tháp Xá Lợi 7 tầng hình lục giác cao 32m ở sân trước lưu giữ xá lợi Phật Thích Ca; lên tầng cao có thể ngắm toàn cảnh quận Tân Bình xanh mát.', 'The oldest Buddhist ancestral pagoda in the old Gia Dinh region, built in 1744 in the "Tam" character layout typical of southern timber-frame houses, with 98 fine wooden pillars carved with recessed Chinese characters. It houses 113 ancient jackfruit-wood statues and an exquisite, over-200-year-old nine-dragon carved altar screen. The 7-story, 32m-tall hexagonal Relic Stupa in the front yard holds relics of the Buddha; climb to the top for a sweeping view of the green Tan Binh district.', 'Tổ đình Phật giáo cổ kính nhất đất Gia Định xây dựng năm 1744 với kiến trúc chữ ''Tam'' kiểu nhà rường Nam Bộ gồm 98 cột gỗ quý khắc chữ Hán chìm. Lưu giữ 113 pho tượng cổ bằng gỗ mít và bộ bao lam chạm cửu long tuyệt mỹ t', 'The oldest Buddhist ancestral pagoda in the old Gia Dinh region, built in 1744 in the "Tam" character layout typical of southern timber-frame houses, with 98 fine wooden pillars carved with recessed Chinese characters.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/chua-giac-lam/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/chua-giac-lam/1.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('1199f3ba-3fa3-40e6-92d5-7e0ab005d3c7', 'Chùa Ngọc Hoàng', 'Jade Emperor Pagoda', 'SG', 'Quận 1', '73 Mai Thị Lựu, P. Đa Kao, Quận 1', 'Di tích tín ngưỡng', 'Tâm linh, Kiến trúc, Yên tĩnh', ARRAY['Tâm linh','Kiến trúc','Yên tĩnh']::text[], 1, 0, 30, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=Ch%C3%B9a%20Ng%E1%BB%8Dc%20Ho%C3%A0ng%2C%20Qu%E1%BA%ADn%201%2C%20TP.%20H%E1%BB%93%20Ch%C3%AD%20Minh', '{"lat": 10.7905, "lng": 106.6935}'::jsonb, 'Ngôi chùa cổ do cộng đồng người Hoa xây dựng đầu thế kỷ 20, nổi tiếng linh thiêng về cầu con cái và cầu duyên lành. Lưu giữ hơn 300 bức tượng điêu khắc gỗ và giấy bồi cổ quý hiếm. Nơi cựu Tổng thống Mỹ Barack Obama từng ghé thăm trong chuyến công du năm 2016. Cầu con cái ghé Điện thờ Kim Hoa Thánh Mẫu và 12 Bà Mụ; cầu tình duyên ghé ban thờ Ông Tơ Bà Nguyệt. Trang phục kín đáo, trang nghiêm khi chiêm bái.', 'An ancient pagoda built by the Chinese community in the early 20th century, renowned for its spiritual power in blessing fertility and good romantic matches. It houses over 300 rare antique wood and papier-mâché carved statues. Former US President Barack Obama visited here during his 2016 state visit. For fertility blessings, visit the shrine of the Lady of Golden Flowers and the Twelve Midwives; for romance, visit the altar of Mr. Silk Thread and Lady Moon. Dress modestly and respectfully when paying your respects.', 'Ngôi chùa cổ do cộng đồng người Hoa xây dựng đầu thế kỷ 20, nổi tiếng linh thiêng về cầu con cái và cầu duyên lành. Lưu giữ hơn 300 bức tượng điêu khắc gỗ và giấy bồi cổ quý hiếm. Nơi cựu Tổng thống Mỹ Barack Obama từng ', 'An ancient pagoda built by the Chinese community in the early 20th century, renowned for its spiritual power in blessing fertility and good romantic matches. It houses over 300 rare antique wood and papier-mâché carved statues.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/chua-ngoc-hoang/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/chua-ngoc-hoang/1.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('d0350642-21ed-4983-9041-66423c20737b', 'Chùa Pháp Hoa & Cung đường Kênh Nhiêu Lộc - Thị Nghè', 'Phap Hoa Pagoda & Nhieu Loc - Thi Nghe Canal', 'SG', 'Quận 3', '870 Trường Sa, P. 14, Quận 3', 'Di tích tín ngưỡng', 'Tâm linh, Kiến trúc, Yên tĩnh', ARRAY['Tâm linh','Kiến trúc','Yên tĩnh']::text[], 1, 0, 30, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=Ch%C3%B9a%20Ph%C3%A1p%20Hoa%20%26%20Cung%20%C4%91%C6%B0%E1%BB%9Dng%20K%C3%AAnh%20Nhi%C3%AAu%20L%E1%BB%99c%20-%20Th%E1%BB%8B%20Ngh%C3%A8%2C%20Qu%E1%BA%ADn%203%2C%20TP.%20H%E1%BB%93%20Ch%C3%AD%20Minh', '{"lat": 10.7958, "lng": 106.6833}'::jsonb, 'Ngôi chùa Phật giáo soi bóng êm đềm bên dòng kênh Nhiêu Lộc - Thị Nghè hồi sinh xanh mát. Chùa nổi tiếng khắp thành phố vào mỗi dịp Đại lễ Phật Đản (tháng 4 Âm lịch) khi hàng vạn ngọn hoa đăng lung linh được thả trôi sáng rực trên mặt nước dọc đường Trường Sa - Hoàng Sa. Trải nghiệm đi thuyền chèo ngắm cảnh kênh Nhiêu Lộc từ bến thuyền Quận 1/Quận 3, vừa nghe đờn ca tài tử vừa ngắm chùa Pháp Hoa rực rỡ hoa đăng từ mặt nước.', 'A Buddhist pagoda that casts its calm reflection on the revitalized, green Nhieu Loc - Thi Nghe Canal. It''s famous citywide every Vesak festival (the 4th lunar month), when tens of thousands of glowing lanterns are set afloat, lighting up the water along Truong Sa and Hoang Sa streets. Try a rowboat tour of the canal from the District 1/District 3 pier, listening to đờn ca tài tử folk music while admiring Phap Hoa Pagoda glowing with lanterns from the water.', 'Ngôi chùa Phật giáo soi bóng êm đềm bên dòng kênh Nhiêu Lộc - Thị Nghè hồi sinh xanh mát. Chùa nổi tiếng khắp thành phố vào mỗi dịp Đại lễ Phật Đản (tháng 4 Âm lịch) khi hàng vạn ngọn hoa đăng lung linh được thả trôi sán', 'A Buddhist pagoda that casts its calm reflection on the revitalized, green Nhieu Loc - Thi Nghe Canal.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/chua-phap-hoa-cung-duong-kenh-nhieu-loc-thi-nghe/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/chua-phap-hoa-cung-duong-kenh-nhieu-loc-thi-nghe/1.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('05e82ea0-25fa-43b7-a520-c20725c90ff2', 'Chùa Vĩnh Nghiêm', 'Vinh Nghiem Pagoda', 'SG', 'Quận 3', '339 Nam Kỳ Khởi Nghĩa, P. Võ Thị Sáu, Quận 3', 'Di tích tín ngưỡng', 'Tâm linh, Kiến trúc, Yên tĩnh', ARRAY['Tâm linh','Kiến trúc','Yên tĩnh']::text[], 1, 0, 30, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=Ch%C3%B9a%20V%C4%A9nh%20Nghi%C3%AAm%2C%20Qu%E1%BA%ADn%203%2C%20TP.%20H%E1%BB%93%20Ch%C3%AD%20Minh', '{"lat": 10.792, "lng": 106.6818}'::jsonb, 'Ngôi chùa bê tông cốt thép kiểu truyền thống đầu tiên tại Việt Nam khánh thành năm 1971, lấy nguyên mẫu từ chùa Vĩnh Nghiêm (Bắc Giang) - chốn tổ thiền phái Trúc Lâm. Điểm nhấn là Tháp Quán Thế Âm 7 tầng cao 40m và Tháp đá Hồng Ân 14m xây hoàn toàn bằng đá xanh Thanh Hóa. Trong chùa có nhà hàng ẩm thực chay Vĩnh Nghiêm nổi tiếng thanh tịnh và ngon miệng. Dịp Đại lễ Phật Đản hay Vu Lan chùa thắp đèn hoa đăng rất đẹp.', 'Vietnam''s first reinforced-concrete pagoda built in a traditional style, completed in 1971 and modeled after Vinh Nghiem Pagoda in Bac Giang, the ancestral home of the Truc Lam Zen sect. Its highlights are the 7-story, 40m Avalokiteshvara Tower and the 14m Hong An stone tower, built entirely from Thanh Hoa green stone. The pagoda has a well-known vegetarian restaurant praised for being both peaceful and delicious. During Vesak or Vu Lan festivals, the pagoda''s lantern displays are especially beautiful.', 'Ngôi chùa bê tông cốt thép kiểu truyền thống đầu tiên tại Việt Nam khánh thành năm 1971, lấy nguyên mẫu từ chùa Vĩnh Nghiêm (Bắc Giang) - chốn tổ thiền phái Trúc Lâm. Điểm nhấn là Tháp Quán Thế Âm 7 tầng cao 40m và Tháp ', 'Vietnam''s first reinforced-concrete pagoda built in a traditional style, completed in 1971 and modeled after Vinh Nghiem Pagoda in Bac Giang, the ancestral home of the Truc Lam Zen sect.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/chua-vinh-nghiem/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/chua-vinh-nghiem/1.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('078f1c1b-dd62-4f8c-a28e-ca1586c85c3c', 'Chung cư Cà phê 42 Nguyễn Huệ', '42 Nguyen Hue Coffee Apartments', 'SG', 'Quận 1', 'Số 42 Nguyễn Huệ, P. Bến Nghé, Quận 1', 'Café', 'Cà phê, Check-in, Thư giãn', ARRAY['Cà phê','Check-in','Thư giãn']::text[], 1, 0, 60, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=Chung%20c%C6%B0%20C%C3%A0%20ph%C3%AA%2042%20Nguy%E1%BB%85n%20Hu%E1%BB%87%2C%20Qu%E1%BA%ADn%201%2C%20TP.%20H%E1%BB%93%20Ch%C3%AD%20Minh', '{"lat": 10.7743, "lng": 106.7033}'::jsonb, 'Khối chung cư 9 tầng xây từ thập niên 1960 được tái sinh ngoạn mục thành tổ hợp hàng chục quán cà phê nghệ thuật độc lạ, tiệm gốm thủ công và thời trang boutique. Mỗi ban công là một ô sắc màu rực rỡ với bảng hiệu neon nhìn thẳng xuống phố đi bộ Nguyễn Huệ. Đi bộ thong thả cầu thang bộ để khám phá những góc cổ điển độc đáo. Chọn quán cafe tầng 5-8 có ban công ngoài trời để ngắm dòng người phố đi bộ.', 'A 9-story apartment block built in the 1960s, dramatically reborn into a complex of dozens of quirky, artsy cafes, handmade ceramics shops, and boutique fashion stores. Each balcony is its own burst of color, with neon signs looking straight down onto Nguyen Hue walking street. Take the stairs slowly to discover unique vintage corners. Pick a cafe on floors 5 to 8 with an open-air balcony for the best view of the crowds below.', 'Khối chung cư 9 tầng xây từ thập niên 1960 được tái sinh ngoạn mục thành tổ hợp hàng chục quán cà phê nghệ thuật độc lạ, tiệm gốm thủ công và thời trang boutique. Mỗi ban công là một ô sắc màu rực rỡ với bảng hiệu neon n', 'A 9-story apartment block built in the 1960s, dramatically reborn into a complex of dozens of quirky, artsy cafes, handmade ceramics shops, and boutique fashion stores.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/chung-cu-ca-phe-42-nguyen-hue/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/chung-cu-ca-phe-42-nguyen-hue/1.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('0e90b269-0839-417a-a087-253872777e48', 'Công viên Văn hóa Đầm Sen', 'Dam Sen Cultural Park', 'SG', 'Quận 11', 'Số 03 Hòa Bình, P. 3, Quận 11', 'Trải nghiệm', 'Check-in, Về đêm, Nhộn nhịp', ARRAY['Check-in','Về đêm','Nhộn nhịp']::text[], 2, 140000, 180, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=C%C3%B4ng%20vi%C3%AAn%20V%C4%83n%20h%C3%B3a%20%C4%90%E1%BA%A7m%20Sen%2C%20Qu%E1%BA%ADn%2011%2C%20TP.%20H%E1%BB%93%20Ch%C3%AD%20Minh', '{"lat": 10.7643, "lng": 106.6376}'::jsonb, 'Tổ hợp giải trí xanh rộng hơn 50ha gồm Đầm Sen Khô với hơn 30 trò chơi cảm giác mạnh, rạp xiếc, thủy cung, vườn chim thú hoang dã và Đầm Sen Nước (Water Park) sở hữu hệ thống máng trượt xoắn ốc khổng lồ và hồ tạo sóng mát lạnh. Dịp bắn pháo hoa Tết và lễ hội lớn, khu vực bờ hồ trung tâm Đầm Sen là điểm ngắm pháo hoa nghệ thuật tầm thấp và mặt nước cực kỳ mãn nhãn.', 'A green entertainment complex spanning over 50 hectares, including Dam Sen Dry Park with more than 30 thrill rides, a circus theater, an aquarium, and a wildlife bird garden, plus Dam Sen Water Park with giant spiral slides and a cool wave pool. During Tet and major festival fireworks displays, the lakeside area at the center of Dam Sen is a stunning spot to watch low-altitude artistic fireworks reflected on the water.', 'Tổ hợp giải trí xanh rộng hơn 50ha gồm Đầm Sen Khô với hơn 30 trò chơi cảm giác mạnh, rạp xiếc, thủy cung, vườn chim thú hoang dã và Đầm Sen Nước (Water Park) sở hữu hệ thống máng trượt xoắn ốc khổng lồ và hồ tạo sóng má', 'A green entertainment complex spanning over 50 hectares, including Dam Sen Dry Park with more than 30 thrill rides, a circus theater, an aquarium, and a wildlife bird garden, plus Dam Sen Water Park with giant spiral slides and a cool wave pool.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/cong-vien-van-hoa-dam-sen/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/cong-vien-van-hoa-dam-sen/1.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('93351361-8a76-44d4-8cc8-f074ef4b5d22', 'Công viên Vinhomes Central Park', 'Vinhomes Central Park', 'SG', 'Bình Thạnh', '208 Nguyễn Hữu Cảnh, P. 22, Q. Bình Thạnh', 'Thiên nhiên', 'Thiên nhiên, Hoang sơ, Thư giãn', ARRAY['Thiên nhiên','Hoang sơ','Thư giãn']::text[], 1, 0, 90, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=C%C3%B4ng%20vi%C3%AAn%20Vinhomes%20Central%20Park%2C%20B%C3%ACnh%20Th%E1%BA%A1nh%2C%20TP.%20H%E1%BB%93%20Ch%C3%AD%20Minh', '{"lat": 10.7954, "lng": 106.7205}'::jsonb, 'Công viên ven sông rộng 14ha với tổng vốn đầu tư hơn 500 tỷ đồng lấy cảm hứng từ Central Park New York. Sở hữu vườn Nhật Bản với hồ cá Koi, cầu gỗ đỏ nghệ thuật, đài phun nước trình diễn ánh sáng, thảm cỏ xanh mướt và đường dạo bộ ven sông ngắm Landmark 81 đồ sộ. Địa điểm dã ngoại bãi cỏ và chụp ảnh toàn cảnh Landmark 81 hoàn hảo từ góc cầu đi bộ vượt hồ hoặc bên bờ bến du thuyền sang trọng.', 'A 14-hectare riverside park with a total investment of over 500 billion VND, inspired by New York''s Central Park. It features a Japanese garden with a koi pond, an artistic red wooden bridge, a light-and-fountain show, lush green lawns, and a riverside promenade with views of the towering Landmark 81. A great spot for a picnic on the grass and for a perfect panoramic photo of Landmark 81 from the footbridge over the lake or from the edge of the upscale marina.', 'Công viên ven sông rộng 14ha với tổng vốn đầu tư hơn 500 tỷ đồng lấy cảm hứng từ Central Park New York. Sở hữu vườn Nhật Bản với hồ cá Koi, cầu gỗ đỏ nghệ thuật, đài phun nước trình diễn ánh sáng, thảm cỏ xanh mướt và đư', 'A 14-hectare riverside park with a total investment of over 500 billion VND, inspired by New York''s Central Park.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/cong-vien-vinhomes-central-park/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/cong-vien-vinhomes-central-park/1.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('83990b44-ec46-4716-bcc8-7859b8990ec8', 'Đền thờ Ấn Độ giáo Mariamman', 'Mariamman Hindu Temple', 'SG', 'Quận 1', '45 Trương Định, P. Bến Thành, Quận 1 (gần chợ Bến Thành)', 'Di tích tín ngưỡng', 'Tâm linh, Kiến trúc, Yên tĩnh', ARRAY['Tâm linh','Kiến trúc','Yên tĩnh']::text[], 1, 0, 20, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=%C4%90%E1%BB%81n%20th%E1%BB%9D%20%E1%BA%A4n%20%C4%90%E1%BB%99%20gi%C3%A1o%20Mariamman%2C%20Qu%E1%BA%ADn%201%2C%20TP.%20H%E1%BB%93%20Ch%C3%AD%20Minh', '{"lat": 10.7724, "lng": 106.6947}'::jsonb, 'Đền thờ Mẹ Mariamman do cộng đồng thương nhân người Ấn gốc Tamil xây dựng đầu thế kỷ 20. Tháp cổng Gopuram vươn cao đắp nổi vô số tượng thần linh sống động đầy màu sắc theo phong cách kiến trúc đền đài Nam Ấn Độ. Cởi giày dép để bên ngoài trước khi vào đền. Tục lệ áp trán vào bức tường đá thiêng phía sau đền và cầu nguyện để đón nhận năng lượng bình an và may mắn.', 'A temple dedicated to Mother Mariamman, built by the Tamil Indian merchant community in the early 20th century. Its towering Gopuram gate rises up, covered in countless vivid, colorful deity statues in the South Indian temple architectural style. Remove your shoes outside before entering. A local custom is to press your forehead against the sacred stone wall behind the temple and pray, to receive peace and good fortune.', 'Đền thờ Mẹ Mariamman do cộng đồng thương nhân người Ấn gốc Tamil xây dựng đầu thế kỷ 20. Tháp cổng Gopuram vươn cao đắp nổi vô số tượng thần linh sống động đầy màu sắc theo phong cách kiến trúc đền đài Nam Ấn Độ.', 'A temple dedicated to Mother Mariamman, built by the Tamil Indian merchant community in the early 20th century. Its towering Gopuram gate rises up, covered in countless vivid, colorful deity statues in the South Indian temple architectural style.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/den-tho-an-do-giao-mariamman/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/den-tho-an-do-giao-mariamman/1.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('692ac71f-b055-4f71-8d40-d147b122106f', 'Đường Sách TP. Hồ Chí Minh', 'Ho Chi Minh City Book Street', 'SG', 'Quận 1', 'Đường Nguyễn Văn Bình, P. Bến Nghé, Quận 1', 'Văn hóa', 'Văn hóa, Nghệ thuật, Sáng tạo', ARRAY['Văn hóa','Nghệ thuật','Sáng tạo']::text[], 1, 0, 30, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=%C4%90%C6%B0%E1%BB%9Dng%20S%C3%A1ch%20TP.%20H%E1%BB%93%20Ch%C3%AD%20Minh%2C%20Qu%E1%BA%ADn%201%2C%20TP.%20H%E1%BB%93%20Ch%C3%AD%20Minh', '{"lat": 10.7799, "lng": 106.6992}'::jsonb, 'Phố đi bộ rợp bóng me cổ thụ dài hơn 100m quy tụ hơn 20 gian hàng nhà xuất bản danh tiếng, quán cà phê sách ngoài trời, triển lãm ảnh nghệ thuật và các buổi tọa đàm ra mắt sách của tác giả nổi tiếng. Ốc đảo bình yên, trang nhã giữa nhịp sống hối hả. Điểm đọc sách và thưởng thức cafe sáng tuyệt vời dưới tán cây râm mát; check-in với xe buýt sách cổ kính và bốt điện thoại phong cách London.', 'A walking street over 100m long, shaded by old tamarind trees, home to more than 20 stalls from well-known publishers, outdoor book cafes, art photo exhibitions, and book-launch talks with famous authors. A peaceful, elegant oasis amid the rush of city life. A great spot to read and enjoy a morning coffee under the shade; snap a photo with the vintage book bus and the London-style phone booth.', 'Phố đi bộ rợp bóng me cổ thụ dài hơn 100m quy tụ hơn 20 gian hàng nhà xuất bản danh tiếng, quán cà phê sách ngoài trời, triển lãm ảnh nghệ thuật và các buổi tọa đàm ra mắt sách của tác giả nổi tiếng. Ốc đảo bình yên, tra', 'A walking street over 100m long, shaded by old tamarind trees, home to more than 20 stalls from well-known publishers, outdoor book cafes, art photo exhibitions, and book-launch talks with famous authors.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/duong-sach-tp-ho-chi-minh/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/duong-sach-tp-ho-chi-minh/1.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('98484f4c-1ad9-439a-96a5-6e1083a85a7d', 'Khu di tích Lịch sử Địa đạo Củ Chi', 'Cu Chi Tunnels Historical Site', 'SG', 'Huyện Củ Chi', 'Xã Phú Mỹ Hưng (Bến Dược) & Xã Nhuận Đức (Bến Đình), Huyện Củ Chi', 'Di tích lịch sử', 'Lịch sử, Hoài cổ, Kiến trúc', ARRAY['Lịch sử','Hoài cổ','Kiến trúc']::text[], 1, 35000, 180, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=Khu%20di%20t%C3%ADch%20L%E1%BB%8Bch%20s%E1%BB%AD%20%C4%90%E1%BB%8Ba%20%C4%91%E1%BA%A1o%20C%E1%BB%A7%20Chi%2C%20Huy%E1%BB%87n%20C%E1%BB%A7%20Chi%2C%20TP.%20H%E1%BB%93%20Ch%C3%AD%20Minh', '{"lat": 11.1407, "lng": 106.4524}'::jsonb, '''Thành phố trong lòng đất'' huyền thoại dài hơn 250km đào hoàn toàn bằng tay thời kháng chiến với hệ thống 3 tầng hầm thông nhau gồm bệnh xá, phòng họp, bếp Hoàng Cầm không khói, kho vũ khí và bẫy chông bí mật. Top 7 công trình ngầm kỳ thú nhất thế giới. Trải nghiệm chui thử vào đoạn hầm địa đạo; thưởng thức củ mì luộc chấm muối mè thơm bùi tại bếp Hoàng Cầm và thử bắn súng thể thao tại trường bắn quốc phòng.', 'A legendary "underground city" over 250km long, dug entirely by hand during the resistance war, with a three-level network of connected tunnels including a clinic, meeting rooms, the smokeless Hoang Cam field kitchen, weapons stores, and hidden booby traps. Ranked among the world''s top 7 most fascinating underground structures. Try crawling through a section of tunnel yourself; enjoy boiled cassava dipped in fragrant sesame salt at the Hoang Cam kitchen, and try sport shooting at the defense firing range.', '''Thành phố trong lòng đất'' huyền thoại dài hơn 250km đào hoàn toàn bằng tay thời kháng chiến với hệ thống 3 tầng hầm thông nhau gồm bệnh xá, phòng họp, bếp Hoàng Cầm không khói, kho vũ khí và bẫy chông bí mật. Top 7 công', 'A legendary "underground city" over 250km long, dug entirely by hand during the resistance war, with a three-level network of connected tunnels including a clinic, meeting rooms, the smokeless Hoang Cam field kitchen, weapons stores, and hidden booby traps.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/khu-di-tich-lich-su-dia-dao-cu-chi/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/khu-di-tich-lich-su-dia-dao-cu-chi/1.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('89a82bcc-341e-457f-8267-2d0ad1f44774', 'Khu Du lịch Văn hóa Suối Tiên', 'Suoi Tien Cultural Tourist Park', 'SG', 'TP. Thủ Đức', '120 Xa lộ Hà Nội, P. Tân Phú, TP. Thủ Đức (Cạnh ga Metro số 1)', 'Trải nghiệm', 'Check-in, Về đêm, Nhộn nhịp', ARRAY['Check-in','Về đêm','Nhộn nhịp']::text[], 2, 150000, 240, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=Khu%20Du%20l%E1%BB%8Bch%20V%C4%83n%20h%C3%B3a%20Su%E1%BB%91i%20Ti%C3%AAn%2C%20TP.%20Th%E1%BB%A7%20%C4%90%E1%BB%A9c%2C%20TP.%20H%E1%BB%93%20Ch%C3%AD%20Minh', '{"lat": 10.8624, "lng": 106.8025}'::jsonb, 'Công viên chuyên đề văn hóa lịch sử thần thoại Việt Nam đầu tiên với diện tích 150ha. Điểm nhấn là biển Tiên Đồng Ngọc Nữ nhân tạo với tượng Lạc Long Quân tạc vào vách núi cao 70m, lâu đài Băng Tuyết lạnh âm 5 độ C, nông trại Suối Tiên Farm và đại cung Tiên Ngư. Có thể di chuyển thẳng từ trung tâm Quận 1 đến cổng Suối Tiên bằng tuyến tàu điện Metro số 1 (Ga Suối Tiên / Bến xe Miền Đông mới) cực kỳ tiện lợi.', 'Vietnam''s first theme park dedicated to history, culture, and mythology, spanning 150 hectares. Highlights include the man-made Tien Dong Ngoc Nu sea, a statue of Lac Long Quan carved into a 70m cliff face, the Ice & Snow Castle kept at minus 5 degrees Celsius, Suoi Tien Farm, and the great Mermaid Palace. You can go straight from downtown District 1 to the Suoi Tien gate on Metro Line 1 (Suoi Tien Station / New Mien Dong Bus Station), making it extremely convenient.', 'Công viên chuyên đề văn hóa lịch sử thần thoại Việt Nam đầu tiên với diện tích 150ha. Điểm nhấn là biển Tiên Đồng Ngọc Nữ nhân tạo với tượng Lạc Long Quân tạc vào vách núi cao 70m, lâu đài Băng Tuyết lạnh âm 5 độ C, nông', 'Vietnam''s first theme park dedicated to history, culture, and mythology, spanning 150 hectares.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/khu-du-lich-van-hoa-suoi-tien/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/khu-du-lich-van-hoa-suoi-tien/1.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('ad4f7ca1-116e-45e4-9ab2-742dfdf89b0d', 'Khu Dự trữ Sinh quyển Rừng ngập mặn Cần Giờ & Đảo Khỉ', 'Can Gio Mangrove Biosphere Reserve & Monkey Island', 'SG', 'Huyện Cần Giờ', 'Xã Long Hòa, Huyện Cần Giờ (cách trung tâm ~45km qua phà Bình Khánh)', 'Thiên nhiên', 'Thiên nhiên, Hoang sơ, Thư giãn', ARRAY['Thiên nhiên','Hoang sơ','Thư giãn']::text[], 1, 35000, 240, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=Khu%20D%E1%BB%B1%20tr%E1%BB%AF%20Sinh%20quy%E1%BB%83n%20R%E1%BB%ABng%20ng%E1%BA%ADp%20m%E1%BA%B7n%20C%E1%BA%A7n%20Gi%E1%BB%9D%20%26%20%C4%90%E1%BA%A3o%20Kh%E1%BB%89%2C%20Huy%E1%BB%87n%20C%E1%BA%A7n%20Gi%E1%BB%9D%2C%20TP.%20H%E1%BB%93%20Ch%C3%AD%20Minh', '{"lat": 10.4113, "lng": 106.9316}'::jsonb, '''Lá phổi xanh'' ven biển của TP.HCM được UNESCO công nhận năm 2000. Quần thể rừng đước bạt ngàn nguyên sinh với hơn 1.000 chú khỉ tự nhiên tại Đảo Khỉ, đi cano xuyên rừng ngập mặn khám phá Chiến khu Rừng Sác huyền thoại và thưởng thức hải sản chợ Hàng Dương. Cẩn thận giữ chặt mắt kính, điện thoại, nón mũ khi vào Đảo Khỉ. Trên đường về nhớ ghé chợ Hàng Dương mua tôm tít, cua biển hấp chấm muối ớt xanh nóng hổi.', 'Ho Chi Minh City''s coastal "green lung," recognized by UNESCO in 2000. A vast, primeval mangrove forest home to over 1,000 wild monkeys on Monkey Island; take a speedboat through the mangroves to explore the legendary Rung Sac resistance base, then enjoy fresh seafood at Hang Duong Market. Hold tightly onto your glasses, phone, and hat when visiting Monkey Island. On the way back, stop by Hang Duong Market for mantis shrimp and steamed crab with hot green chili salt.', '''Lá phổi xanh'' ven biển của TP.HCM được UNESCO công nhận năm 2000. Quần thể rừng đước bạt ngàn nguyên sinh với hơn 1.000 chú khỉ tự nhiên tại Đảo Khỉ, đi cano xuyên rừng ngập mặn khám phá Chiến khu Rừng Sác huyền thoại v', 'Ho Chi Minh City''s coastal "green lung," recognized by UNESCO in 2000.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/khu-du-tru-sinh-quyen-rung-ngap-man-can-gio-dao-khi/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/khu-du-tru-sinh-quyen-rung-ngap-man-can-gio-dao-khi/1.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('a961b420-c03b-43ea-9e87-5d10b763e9ec', 'L''Usine Café & Restaurant', 'L''Usine Cafe & Restaurant', 'SG', 'Quận 1', '70 Lê Lợi, P. Bến Thành, Quận 1', 'Café', 'Pháp, nghệ thuật, tinh tế', ARRAY['Pháp','Nghệ thuật','tinh tế']::text[], 2, 80000, 60, NULL, '08:00', '22:00', NULL, NULL, NULL, '{"lat": 10.7736, "lng": 106.7012}'::jsonb, 'Trong những bức tường cũ kỳ lạ, cà phê thơm ngào ngạt hòa lẫn với hương thời gian, nơi mỗi góc là một câu chuyện im lặng chờ được khám phá. Tại đây, nghệ thuật và vị cà phê tinh tế gặp gỡ như một buổi hẹn định mệnh, mời bạn vào một thế giới không thuộc về hiện tại. Bạn sẽ hiểu vì sao những người yêu cái đẹp lại lặng lẽ trở lại nơi này, lần lần, như một bí mật được gìn giữ.', 'Within these curiously old walls, the rich scent of coffee mingles with the scent of time itself, where every corner holds a quiet story waiting to be discovered. Here, art and refined coffee meet like a fated rendezvous, inviting you into a world that doesn''t quite belong to the present. You''ll understand why lovers of beauty keep quietly coming back to this place, again and again, like a secret worth keeping.', 'Café-boutique-gallery trong tòa nhà Pháp cổ, kết hợp cà phê chất lượng cao với thời trang và nghệ thuật — điểm đến của giới tinh tế Sài Gòn.', 'A cafe-boutique-gallery inside an old French building, blending high-quality coffee with fashion and art, a destination for Saigon''s style-conscious crowd.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/l-usine-cafe-restaurant/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/l-usine-cafe-restaurant/1.jpg', true, false, true, '2026-07-23T13:26:06.903962+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('b4eae634-8d03-4187-97dd-cc67bee99106', 'Làng Du lịch Sinh thái Nông trang Xanh', 'Green Farm Eco-Tourism Village', 'SG', 'Huyện Củ Chi', '816/18 Nguyễn Thị Rành, Xã An Nhơn Tây, Huyện Củ Chi', 'Du lịch sinh thái', 'Thiên nhiên, Thư giãn, Gia đình', ARRAY['Thiên nhiên','Thư giãn','Gia đình']::text[], 1, 50000, 150, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=L%C3%A0ng%20Du%20l%E1%BB%8Bch%20Sinh%20th%C3%A1i%20N%C3%B4ng%20trang%20Xanh%2C%20Huy%E1%BB%87n%20C%E1%BB%A7%20Chi%2C%20TP.%20H%E1%BB%93%20Ch%C3%AD%20Minh', '{"lat": 11.0167, "lng": 106.5167}'::jsonb, 'Trang trại nông nghiệp hữu cơ xanh mát rộng hơn 20ha theo mô hình Nhật Bản và Hàn Quốc. Du khách được tự tay hái nấm linh chi, hái dưa lưới công nghệ cao, vắt sữa bò sữa, thăm chuồng cừu dê, cưỡi ngựa và thưởng thức ẩm thực từ nông sản sạch tại chỗ. Trải nghiệm ''chữa lành'' xả stress tuyệt vời cho gia đình và trẻ nhỏ tiếp xúc thiên nhiên; có dịch vụ homestay nhà tre mộc mạc bên hồ sen.', 'A lush organic farm spanning over 20 hectares, modeled on Japanese and Korean farming methods. Visitors get to pick their own reishi mushrooms and high-tech cantaloupes, milk dairy cows, visit the sheep and goat pens, ride horses, and enjoy meals made from fresh, locally grown produce. A great "healing," stress-relieving experience for families and kids to connect with nature; rustic bamboo homestay lodging by a lotus pond is also available.', 'Trang trại nông nghiệp hữu cơ xanh mát rộng hơn 20ha theo mô hình Nhật Bản và Hàn Quốc. Du khách được tự tay hái nấm linh chi, hái dưa lưới công nghệ cao, vắt sữa bò sữa, thăm chuồng cừu dê, cưỡi ngựa và thưởng thức ẩm t', 'A lush organic farm spanning over 20 hectares, modeled on Japanese and Korean farming methods.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/lang-du-lich-sinh-thai-nong-trang-xanh/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/lang-du-lich-sinh-thai-nong-trang-xanh/1.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('e21454ea-15fe-4bc3-b9da-ecd3adf65a41', 'Lăng Tả quân Lê Văn Duyệt', 'Ta Quan Le Van Duyet Tomb', 'SG', 'Bình Thạnh', 'Số 01 Vũ Tùng, P. 1, Q. Bình Thạnh (cạnh chợ Bà Chiểu)', 'Di tích lịch sử', 'Lịch sử, Hoài cổ, Kiến trúc', ARRAY['Lịch sử','Hoài cổ','Kiến trúc']::text[], 1, 0, 30, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=L%C4%83ng%20T%E1%BA%A3%20qu%C3%A2n%20L%C3%AA%20V%C4%83n%20Duy%E1%BB%87t%2C%20B%C3%ACnh%20Th%E1%BA%A1nh%2C%20TP.%20H%E1%BB%93%20Ch%C3%AD%20Minh', '{"lat": 10.801, "lng": 106.6975}'::jsonb, 'Nơi an nghỉ của Tổng trấn Gia Định Thành Tả quân Lê Văn Duyệt và phu nhân. Quần thể rộng 18.500m2 rợp bóng cổ thụ mang kiến trúc cung đình triều Nguyễn gồm Nhà bia, Mộ phần xây theo kiểu ''mộ quy'' bằng hợp chất ô dước cổ và Thượng điện chạm rồng phượng tinh vi. Dịp Tết Nguyên Đán và lễ giỗ Tả quân (mùng 1-3/8 Âm lịch), lăng diễn ra các nghi lễ tế cung đình trang trọng, diễn hát bội truyền thống và xin xăm đầu năm.', 'The resting place of Ta Quan Le Van Duyet, Governor-General of Gia Dinh, and his wife. The 18,500-square-meter complex, shaded by ancient trees, features Nguyen-dynasty royal architecture, including a stele house, a "tortoise-shaped" tomb built from traditional lime mortar, and a main hall with intricately carved dragon-and-phoenix motifs. During Tet and the Ta Quan memorial festival (the 1st-3rd of the 8th lunar month), the tomb hosts solemn royal-style rites, traditional hat boi opera performances, and New Year fortune-telling.', 'Nơi an nghỉ của Tổng trấn Gia Định Thành Tả quân Lê Văn Duyệt và phu nhân. Quần thể rộng 18.500m2 rợp bóng cổ thụ mang kiến trúc cung đình triều Nguyễn gồm Nhà bia, Mộ phần xây theo kiểu ''mộ quy'' bằng hợp chất ô dước cổ ', 'The resting place of Ta Quan Le Van Duyet, Governor-General of Gia Dinh, and his wife.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/lang-ta-quan-le-van-duyet/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/lang-ta-quan-le-van-duyet/1.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('7dc6251f-8cf7-4df4-8d43-48c01af15b7f', 'Nhà hát Thành phố', 'Saigon Opera House', 'SG', 'Quận 1', 'Số 07 Công Trường Lam Sơn, P. Bến Nghé, Quận 1', 'Văn hóa', 'Văn hóa, Nghệ thuật, Sáng tạo', ARRAY['Văn hóa','Nghệ thuật','Sáng tạo']::text[], 1, 0, 30, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=Nh%C3%A0%20h%C3%A1t%20Th%C3%A0nh%20ph%E1%BB%91%2C%20Qu%E1%BA%ADn%201%2C%20TP.%20H%E1%BB%93%20Ch%C3%AD%20Minh', '{"lat": 10.7765, "lng": 106.703}'::jsonb, 'Khánh thành năm 1900 theo phong cách Flamboyant Gothic của Đệ tam Cộng hòa Pháp với mặt tiền chạm khắc phù điêu nữ thần tinh xảo, khán phòng 468 ghế hình vòm. Nơi diễn ra các show diễn nghệ thuật đỉnh cao như ''À Ố Show'', vở kịch nghệ và hòa nhạc hàn lâm. Ngồi bậc thềm bên hông nhà hát hoặc quán cafe đối diện để ngắm dòng xe đại lộ Đồng Khởi và khách sạn Continental cổ kính.', 'Completed in 1900 in the Flamboyant Gothic style of the French Third Republic, with an ornately carved goddess relief facade and a domed 468-seat auditorium. Home to top-tier performances such as the "A O Show," theatrical plays, and classical concerts. Sit on the side steps of the theatre or at a cafe across the street to watch the traffic along Dong Khoi Boulevard and admire the historic Continental Hotel.', 'Khánh thành năm 1900 theo phong cách Flamboyant Gothic của Đệ tam Cộng hòa Pháp với mặt tiền chạm khắc phù điêu nữ thần tinh xảo, khán phòng 468 ghế hình vòm. Nơi diễn ra các show diễn nghệ thuật đỉnh cao như ''À Ố Show'',', 'Completed in 1900 in the Flamboyant Gothic style of the French Third Republic, with an ornately carved goddess relief facade and a domed 468-seat auditorium.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/nha-hat-thanh-pho/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/nha-hat-thanh-pho/1.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('b8d819b8-953d-4ba0-ae1a-4f39bcd89d57', 'Nhà thờ Cha Tam', 'Cha Tam Church', 'SG', 'Quận 5', '25 Học Lạc, P. 14, Quận 5', 'Di tích tín ngưỡng', 'Tâm linh, Kiến trúc, Yên tĩnh', ARRAY['Tâm linh','Kiến trúc','Yên tĩnh']::text[], 1, 0, 30, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=Nh%C3%A0%20th%E1%BB%9D%20Cha%20Tam%2C%20Qu%E1%BA%ADn%205%2C%20TP.%20H%E1%BB%93%20Ch%C3%AD%20Minh', '{"lat": 10.751, "lng": 106.6578}'::jsonb, 'Khánh thành năm 1902 do Linh mục Pierre d''Assonville (Cha Tam) chủ trì xây dựng cho giáo dân người Hoa. Kiến trúc giao thoa Đông - Tây độc đáo: tháp chuông Gothic kết hợp mái ngói âm dương, cuốn thư câu đối chữ Hán và tượng hoa sen chạm khắc tinh vi. Nơi ghi dấu sự kiện lịch sử ngày 2/11/1963. Sau khi tham quan có thể đi bộ sang chợ vải Soái Kình Lâm và khu phố sủi cảo Hà Tôn Quyền kế bên.', 'Completed in 1902 under the direction of Father Pierre d''Assonville (known as Cha Tam), built for the local Chinese Catholic community. Its architecture is a unique East-West blend: a Gothic bell tower combined with yin-yang roof tiles, Chinese-character scroll couplets, and finely carved lotus-flower sculptures. The site marks the historic events of November 2, 1963. After visiting, you can walk over to the Soai Kinh Lam fabric market and the nearby Ha Ton Quyen dumpling street.', 'Khánh thành năm 1902 do Linh mục Pierre d''Assonville (Cha Tam) chủ trì xây dựng cho giáo dân người Hoa. Kiến trúc giao thoa Đông - Tây độc đáo: tháp chuông Gothic kết hợp mái ngói âm dương, cuốn thư câu đối chữ Hán và tư', 'Completed in 1902 under the direction of Father Pierre d''Assonville (known as Cha Tam), built for the local Chinese Catholic community.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/nha-tho-cha-tam/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/nha-tho-cha-tam/1.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('9f6ae4cf-e7dd-4491-8241-2526a540912f', 'Nhà thờ Đức Bà Sài Gòn', 'Notre-Dame Cathedral Basilica of Saigon', 'SG', 'Quận 1', 'Số 01 Công xã Paris, P. Bến Nghé, Quận 1', 'Di tích tín ngưỡng', 'Tâm linh, Kiến trúc, Yên tĩnh', ARRAY['Tâm linh','Kiến trúc','Yên tĩnh']::text[], 1, 0, 30, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=Nh%C3%A0%20th%E1%BB%9D%20%C4%90%E1%BB%A9c%20B%C3%A0%20S%C3%A0i%20G%C3%B2n%2C%20Qu%E1%BA%ADn%201%2C%20TP.%20H%E1%BB%93%20Ch%C3%AD%20Minh', '{"lat": 10.7797, "lng": 106.699}'::jsonb, 'Vương cung thánh đường tuyệt mỹ khởi công năm 1877 theo phong cách Roman pha lẫn Gothic. Toàn bộ gạch đỏ ngói Marseille được vận chuyển trực tiếp từ Pháp, hai tháp chuông cao 57m sừng sững giữa trung tâm. Phía trước là tượng Đức Mẹ Hòa Bình bằng đá cẩm thạch trắng Carrara. Thưởng thức ''cà phê bệt'' công viên 30/4 đối diện hoặc chụp từ góc Bưu điện Thành phố sang để lấy trọn vẹn hai tháp chuông sừng sững.', 'A stunning basilica, construction begun in 1877, blending Romanesque and Gothic styles. Every red brick and Marseille roof tile was shipped directly from France, and its two 57m bell towers stand tall at the heart of the city. In front stands a statue of Our Lady of Peace, carved from white Carrara marble. Grab a "sit-on-the-grass coffee" in the 30/4 Park across the street, or shoot from the angle of the Central Post Office to capture both towering bell towers in full.', 'Vương cung thánh đường tuyệt mỹ khởi công năm 1877 theo phong cách Roman pha lẫn Gothic. Toàn bộ gạch đỏ ngói Marseille được vận chuyển trực tiếp từ Pháp, hai tháp chuông cao 57m sừng sững giữa trung tâm. Phía trước là t', 'A stunning basilica, construction begun in 1877, blending Romanesque and Gothic styles. Every red brick and Marseille roof tile was shipped directly from France, and its two 57m bell towers stand tall at the heart of the city.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/nha-tho-duc-ba-sai-gon/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/nha-tho-duc-ba-sai-gon/1.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('43db0683-5239-4762-b3c3-ca612a46b22b', 'Ơi Cafe', 'Oi Cafe', 'SG', 'Quận 3', '15B/4 Trần Cao Vân, P.6, Quận 3', 'Café', 'vintage Sài Gòn, hoài cổ, ấm cúng', ARRAY['vintage Sài Gòn','Hoài cổ','ấm cúng']::text[], 2, 80000, 60, NULL, '07:30', '22:00', NULL, NULL, NULL, '{"lat": 10.782, "lng": 106.6892}'::jsonb, 'Những bức ảnh đen trắng kể chuyện, những giai điệu vàng xưa vang vọng từ góc tối, và hương cà phê quen thuộc hòa cùng không khí hoài cổ. Đây là nơi thời gian dừng lại, nơi những chiếc ghế cũ và tường cũ đều có linh hồn. Bạn sẽ tìm thấy chính mình trong từng góc quán, trong mỗi kỷ niệm chưa kịp quên.', 'Black-and-white photos tell their own stories, old golden-era songs echo from dim corners, and the familiar scent of coffee blends with a nostalgic air. Here, time seems to stop, and even the worn chairs and old walls feel like they have a soul. You''ll find a piece of yourself in every corner of this cafe, in every memory not quite forgotten.', 'Quán như bước vào ngôi nhà Sài Gòn xưa với đồ nội thất cổ, ảnh đen trắng và nhạc vàng — liều thuốc hoài niệm cho người Sài Gòn.', 'A cafe that feels like stepping into an old Saigon home, with antique furniture, black-and-white photos, and golden-era music, a dose of nostalgia for Saigon locals.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/oi-cafe/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/oi-cafe/1.jpg', true, false, true, '2026-07-23T13:26:06.903962+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('750e5f29-fc20-473c-a0bc-d7c29da10701', 'Phố ẩm thực Hà Tôn Quyền', 'Ha Ton Quyen Food Street', 'SG', 'Quận 11', 'Đường Hà Tôn Quyền, P. 4, Quận 11 (Khu giáp ranh Chợ Lớn Q5)', 'Ẩm thực', 'Ẩm thực, Về đêm, Nhộn nhịp', ARRAY['Ẩm thực','Về đêm','Nhộn nhịp']::text[], 1, 50000, 60, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=Ph%E1%BB%91%20%E1%BA%A9m%20th%E1%BB%B1c%20H%C3%A0%20T%C3%B4n%20Quy%E1%BB%81n%2C%20Qu%E1%BA%ADn%2011%20%26%20Qu%E1%BA%ADn%205%2C%20TP.%20H%E1%BB%93%20Ch%C3%AD%20Minh', '{"lat": 10.757, "lng": 106.652}'::jsonb, 'Thủ phủ sủi cảo nức tiếng nhất miền Nam của người Hoa gốc Quảng Đông. Con phố thơm nức mùi nước lèo ninh tôm mực ngọt thanh, những viên sủi cảo nhân tôm tươi nguyên con bọc vỏ bánh vàng óng giòn dai, sủi cảo chiên giòn, sủi cảo thập cẩm ăn kèm mực ngâm tro và cải ngọt. Nên thử quán sủi cảo Ngọc Ý, Thiên Thiên hoặc Như Ý. Kêu một tô sủi cảo thập cẩm có tôm, mực ngâm tro, bong bóng cá và một đĩa sủi cảo chiên giòn chấm xì dầu giấm đỏ.', 'The most famous dumpling (sui cao) capital in southern Vietnam, rooted in Cantonese Chinese cuisine. The street is fragrant with sweet shrimp-and-squid broth, whole-shrimp dumplings wrapped in golden, chewy-crisp skins, fried dumplings, and mixed dumplings served with lime-cured squid and mustard greens. Worth trying: Ngoc Y, Thien Thien, or Nhu Y dumpling shops. Order a bowl of mixed dumplings with shrimp, lime-cured squid, and fish swim bladder, plus a plate of crispy fried dumplings dipped in red vinegar soy sauce.', 'Thủ phủ sủi cảo nức tiếng nhất miền Nam của người Hoa gốc Quảng Đông. Con phố thơm nức mùi nước lèo ninh tôm mực ngọt thanh, những viên sủi cảo nhân tôm tươi nguyên con bọc vỏ bánh vàng óng giòn dai, sủi cảo chiên giòn, ', 'The most famous dumpling (sui cao) capital in southern Vietnam, rooted in Cantonese Chinese cuisine.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/pho-am-thuc-ha-ton-quyen/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/pho-am-thuc-ha-ton-quyen/1.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('6ad302ec-2552-4d5a-8343-dfc3ca7d6fa4', 'Phố đi bộ Bùi Viện & Phố Tây Phạm Ngũ Lão', 'Bui Vien Walking Street & Pham Ngu Lao Backpacker Quarter', 'SG', 'Quận 1', 'Đường Bùi Viện - Phạm Ngũ Lão, P. Phạm Ngũ Lão, Quận 1', 'Trải nghiệm', 'Check-in, Về đêm, Nhộn nhịp', ARRAY['Check-in','Về đêm','Nhộn nhịp']::text[], 1, 0, 120, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=Ph%E1%BB%91%20%C4%91i%20b%E1%BB%99%20B%C3%B9i%20Vi%E1%BB%87n%20%26%20Ph%E1%BB%91%20T%C3%A2y%20Ph%E1%BA%A1m%20Ng%C5%A9%20L%C3%A3o%2C%20Qu%E1%BA%ADn%201%2C%20TP.%20H%E1%BB%93%20Ch%C3%AD%20Minh', '{"lat": 10.768, "lng": 106.6927}'::jsonb, 'Khu ''phố Tây ba lô'' không ngủ lừng danh Sài Gòn. Khi màn đêm buông xuống, con phố bừng sáng với âm nhạc EDM sôi động từ các pub/bar ngoài trời, các quán bia sệt vỉa hè, các tiết mục xiếc múa lửa đường phố và ẩm thực đa quốc gia phong phú. Ngồi ghế nhựa vỉa hè thưởng thức bia Sài Gòn ướp lạnh, nhắm cùng đậu phộng rang tỏi ớt hoặc khô mực chiên nước mắm để cảm nhận trọn vẹn nhịp sống nightlife.', 'Saigon''s famous sleepless "backpacker quarter." As night falls, the street lights up with pumping EDM from open-air pubs and bars, sidewalk draft-beer stalls, street fire-dancing performances, and a rich mix of international food. Grab a plastic stool on the sidewalk, sip an ice-cold Saigon beer with chili-garlic peanuts or fish-sauce-fried dried squid, and soak up the full nightlife vibe.', 'Khu ''phố Tây ba lô'' không ngủ lừng danh Sài Gòn. Khi màn đêm buông xuống, con phố bừng sáng với âm nhạc EDM sôi động từ các pub/bar ngoài trời, các quán bia sệt vỉa hè, các tiết mục xiếc múa lửa đường phố và ẩm thực đa q', 'Saigon''s famous sleepless "backpacker quarter."', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/pho-di-bo-bui-vien-pho-tay-pham-ngu-lao/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/pho-di-bo-bui-vien-pho-tay-pham-ngu-lao/1.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('121e22dc-b267-435f-8f49-d01fd17d68b4', 'Phố đi bộ Nguyễn Huệ & Trục cảnh quan trung tâm', 'Nguyen Hue Walking Street & Central Landscape Axis', 'SG', 'Quận 1', 'Đại lộ Nguyễn Huệ, P. Bến Nghé, Quận 1', 'Trải nghiệm', 'Check-in, Về đêm, Nhộn nhịp', ARRAY['Check-in','Về đêm','Nhộn nhịp']::text[], 1, 0, 60, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=Ph%E1%BB%91%20%C4%91i%20b%E1%BB%99%20Nguy%E1%BB%85n%20Hu%E1%BB%87%20%26%20Tr%E1%BB%A5c%20c%E1%BA%A3nh%20quan%20trung%20t%C3%A2m%2C%20Qu%E1%BA%ADn%201%2C%20TP.%20H%E1%BB%93%20Ch%C3%AD%20Minh', '{"lat": 10.7745, "lng": 106.7032}'::jsonb, 'Quảng trường đi bộ lát đá granite hiện đại dài 670m rộng 64m kết nối từ Tòa thị chính ra bờ sông Sài Gòn. Nơi diễn ra các lễ hội văn hóa lớn, đường hoa Tết thường niên, nhạc nước nghệ thuật ngầm và tụ điểm giao lưu văn hóa đường phố (busking) sôi động nhất của giới trẻ. Thử món trà sữa, kem bơ hoặc bánh tráng trộn vỉa hè; thưởng thức các ban nhạc acoustic và nhóm nhảy hiphop biểu diễn đường phố tự do.', 'A modern granite-paved pedestrian plaza, 670m long and 64m wide, connecting City Hall to the banks of the Saigon River. Home to major cultural festivals, the annual Tet flower street, underground musical fountain shows, and the city''s liveliest street-busking scene for young people. Try bubble tea, avocado ice cream, or mixed rice-paper salad from sidewalk stalls; enjoy free acoustic bands and hip-hop dance crews performing on the street.', 'Quảng trường đi bộ lát đá granite hiện đại dài 670m rộng 64m kết nối từ Tòa thị chính ra bờ sông Sài Gòn. Nơi diễn ra các lễ hội văn hóa lớn, đường hoa Tết thường niên, nhạc nước nghệ thuật ngầm và tụ điểm giao lưu văn h', 'A modern granite-paved pedestrian plaza, 670m long and 64m wide, connecting City Hall to the banks of the Saigon River.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/pho-di-bo-nguyen-hue-truc-canh-quan-trung-tam/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/pho-di-bo-nguyen-hue-truc-canh-quan-trung-tam/1.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('218693ba-e03d-46a4-bbf6-2a51d31cb64d', 'Phố đồ cổ & tranh ảnh Lê Công Kiều', 'Le Cong Kieu Antique & Art Street', 'SG', 'Quận 1', 'Đường Lê Công Kiều, P. Nguyễn Thái Bình, Quận 1', 'Trải nghiệm', 'Check-in, Về đêm, Nhộn nhịp', ARRAY['Check-in','Về đêm','Nhộn nhịp']::text[], 1, 0, 45, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=Ph%E1%BB%91%20%C4%91%E1%BB%93%20c%E1%BB%95%20%26%20tranh%20%E1%BA%A3nh%20L%C3%AA%20C%C3%B4ng%20Ki%E1%BB%81u%2C%20Qu%E1%BA%ADn%201%2C%20TP.%20H%E1%BB%93%20Ch%C3%AD%20Minh', '{"lat": 10.7709, "lng": 106.6963}'::jsonb, 'Con phố đồ cổ ngắn nhưng danh tiếng bậc nhất Đông Nam Á dài 200m quy tụ hàng chục cửa hàng trưng bày tiền cổ, đồ đồng thời Nguyễn, gốm sứ Chu Đậu, đồ gỗ cẩn xà cừ, máy hát đĩa than và các kỷ vật thời kỳ Đông Dương. Địa điểm yêu thích của những tâm hồn hoài cổ (vintage). Khi tham quan hãy cẩn thận tránh va quẹt vào các hiện vật gốm sứ quý giá trưng bày ngoài hiên.', 'A short but famous antique street, just 200m long, yet one of the most renowned in Southeast Asia, lined with dozens of shops displaying antique coins, Nguyen-dynasty bronzeware, Chu Dau ceramics, mother-of-pearl inlaid furniture, vinyl record players, and Indochine-era keepsakes. A favorite haunt for vintage-loving souls. When browsing, be careful not to bump into the precious ceramic pieces displayed out on the sidewalk.', 'Con phố đồ cổ ngắn nhưng danh tiếng bậc nhất Đông Nam Á dài 200m quy tụ hàng chục cửa hàng trưng bày tiền cổ, đồ đồng thời Nguyễn, gốm sứ Chu Đậu, đồ gỗ cẩn xà cừ, máy hát đĩa than và các kỷ vật thời kỳ Đông Dương.', 'A short but famous antique street, just 200m long, yet one of the most renowned in Southeast Asia, lined with dozens of shops displaying antique coins, Nguyen-dynasty bronzeware, Chu Dau ceramics, mother-of-pearl inlaid furniture, vinyl record players, and Indochine-era keepsakes.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/pho-do-co-tranh-anh-le-cong-kieu/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/pho-do-co-tranh-anh-le-cong-kieu/1.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('f7ea713a-57f2-473a-a7ad-5971a43cfcd1', 'Phố lồng đèn Lương Nhữ Học', 'Luong Nhu Hoc Lantern Street', 'SG', 'Quận 5', 'Tuyến đường Lương Nhữ Học - Nguyễn Trãi, P. 11, Quận 5', 'Trải nghiệm', 'Check-in, Về đêm, Nhộn nhịp', ARRAY['Check-in','Về đêm','Nhộn nhịp']::text[], 1, 0, 45, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=Ph%E1%BB%91%20l%E1%BB%93ng%20%C4%91%C3%A8n%20L%C6%B0%C6%A1ng%20Nh%E1%BB%AF%20H%E1%BB%8Dc%2C%20Qu%E1%BA%ADn%205%2C%20TP.%20H%E1%BB%93%20Ch%C3%AD%20Minh', '{"lat": 10.7533, "lng": 106.6613}'::jsonb, 'Con phố thủ công truyền thống rực rỡ nhất Sài Gòn mỗi dịp Tết Trung Thu và Tết Nguyên Đán. Hàng trăm cửa tiệm treo kín hàng vạn chiếc lồng đèn giấy kính đỏ hình cá chép, rồng bay, đèn kéo quân và đèn lồng lụa Hội An lung linh tỏa sáng cả góc trời Chợ Lớn. Nên đi vào các ngày đầu tháng 8 Âm lịch để tránh quá tải chen chúc. Hãy ủng hộ các cửa hàng 1-2 chiếc lồng đèn nhỏ xinh trước khi chụp ảnh check-in.', 'Saigon''s most dazzling traditional craft street every Mid-Autumn Festival and Lunar New Year. Hundreds of shops are draped in tens of thousands of red glass-paper lanterns shaped like carp and flying dragons, spinning shadow lanterns, and shimmering Hoi An silk lanterns, lighting up this whole corner of Cho Lon. It''s best to go in the first days of the 8th lunar month to avoid overwhelming crowds. Please support the shops by buying a cute little lantern or two before you start snapping photos.', 'Con phố thủ công truyền thống rực rỡ nhất Sài Gòn mỗi dịp Tết Trung Thu và Tết Nguyên Đán. Hàng trăm cửa tiệm treo kín hàng vạn chiếc lồng đèn giấy kính đỏ hình cá chép, rồng bay, đèn kéo quân và đèn lồng lụa Hội An lung', 'Saigon''s most dazzling traditional craft street every Mid-Autumn Festival and Lunar New Year.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/pho-long-den-luong-nhu-hoc/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/pho-long-den-luong-nhu-hoc/1.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('4795b15d-711f-4c0e-b5b1-c57ea4a11d33', 'Thánh đường Hồi giáo Jamia Al-Musulman', 'Jamia Al-Musulman Mosque', 'SG', 'Quận 1', '66 Đông Du, P. Bến Nghé, Quận 1', 'Di tích tín ngưỡng', 'Tâm linh, Kiến trúc, Yên tĩnh', ARRAY['Tâm linh','Kiến trúc','Yên tĩnh']::text[], 1, 0, 20, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=Th%C3%A1nh%20%C4%91%C6%B0%E1%BB%9Dng%20H%E1%BB%93i%20gi%C3%A1o%20Jamia%20Al-Musulman%2C%20Qu%E1%BA%ADn%201%2C%20TP.%20H%E1%BB%93%20Ch%C3%AD%20Minh', '{"lat": 10.7791, "lng": 106.7034}'::jsonb, 'Xây dựng năm 1935 phục vụ cộng đồng tín đồ Hồi giáo từ Nam Á. Nét kiến trúc Hồi giáo đặc trưng với màu sơn xanh ngọc bích - trắng pastel thanh thoát, mái vòm hình củ hành, tháp Minaret và hành lang lát đá cẩm thạch mát lạnh yên ắng giữa trung tâm sầm uất. Khuôn viên phía sau thánh đường có quầy ẩm thực Halal chuẩn vị bán các món cà ri bò cay nồng, cơm Biryani, bánh Roti Canai rất hấp dẫn.', 'Built in 1935 to serve the local Muslim community from South Asia. Its distinctive Islamic architecture features an elegant jade-green and pastel white color scheme, an onion-shaped dome, a minaret tower, and a cool, quiet marble corridor tucked amid the bustling city center. In the courtyard behind the mosque, Halal food stalls serve up tempting spicy beef curry, biryani rice, and roti canai.', 'Xây dựng năm 1935 phục vụ cộng đồng tín đồ Hồi giáo từ Nam Á. Nét kiến trúc Hồi giáo đặc trưng với màu sơn xanh ngọc bích - trắng pastel thanh thoát, mái vòm hình củ hành, tháp Minaret và hành lang lát đá cẩm thạch mát l', 'Built in 1935 to serve the local Muslim community from South Asia.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/thanh-duong-hoi-giao-jamia-al-musulman/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/thanh-duong-hoi-giao-jamia-al-musulman/1.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('2a1ed345-6898-4bc0-af2c-c2e4f6446b3c', 'Thảo Cầm Viên Sài Gòn', 'Saigon Zoo and Botanical Garden', 'SG', 'Quận 1', 'Số 02 Nguyễn Bỉnh Khiêm, P. Bến Nghé, Quận 1', 'Thiên nhiên', 'Thiên nhiên, Hoang sơ, Thư giãn', ARRAY['Thiên nhiên','Hoang sơ','Thư giãn']::text[], 2, 60000, 120, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=Th%E1%BA%A3o%20C%E1%BA%A7m%20Vi%C3%AAn%20S%C3%A0i%20G%C3%B2n%2C%20Qu%E1%BA%ADn%201%2C%20TP.%20H%E1%BB%93%20Ch%C3%AD%20Minh', '{"lat": 10.7878, "lng": 106.7055}'::jsonb, 'Xây dựng từ năm 1864, là vườn thú lâu đời thứ 8 trên thế giới và là ''lá phổi xanh'' cổ thụ giữa lòng thành phố. Bảo tồn hơn 1.300 cá thể động vật thuộc 125 loài quý hiếm cùng hơn 2.500 cây gỗ đại thụ quý giá, vườn phong lan, nhà xương rồng và hồ sen thanh tịnh. Địa điểm dã ngoại số 1 cho gia đình có trẻ nhỏ. Thuê xe điện dạo quanh vườn thú hoặc mang thảm cắm trại dã ngoại dưới bóng cây me tây trăm tuổi.', 'Built in 1864, it''s the 8th-oldest zoo in the world and a venerable "green lung" at the heart of the city. It conserves over 1,300 animals across 125 rare species, alongside more than 2,500 precious old-growth trees, an orchid garden, a cactus house, and a tranquil lotus pond. The number-one picnic spot for families with young kids. Rent an electric cart to tour the zoo, or bring a picnic mat and relax under the shade of century-old rain trees.', 'Xây dựng từ năm 1864, là vườn thú lâu đời thứ 8 trên thế giới và là ''lá phổi xanh'' cổ thụ giữa lòng thành phố. Bảo tồn hơn 1.300 cá thể động vật thuộc 125 loài quý hiếm cùng hơn 2.500 cây gỗ đại thụ quý giá, vườn phong l', 'Built in 1864, it''s the 8th-oldest zoo in the world and a venerable "green lung" at the heart of the city.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/thao-cam-vien-sai-gon/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/thao-cam-vien-sai-gon/1.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('9ddb0d2d-e51b-4b41-ba76-6aa4cc8a23ce', 'The Workshop Coffee', 'The Workshop Coffee', 'SG', 'Quận 1', '27 Ngô Đức Kế, P. Bến Nghé, Quận 1', 'Café', 'specialty coffee, industrial, chill', ARRAY['specialty coffee','industrial','chill']::text[], 2, 80000, 60, NULL, '08:00', '21:00', NULL, NULL, NULL, '{"lat": 10.7731, "lng": 106.7034}'::jsonb, 'Những tầng lầu ẩn chứa mùi hương cà phê đặc biệt, nơi những người sáng tạo tìm kiếm cảm hứng giữa không gian công nghiệp thô mộc. Từ hạt cà phê được chọn lọc kỹ lưỡng đến từng tách nước được rót với tâm huyết, mỗi chi tiết tại đây kể một câu chuyện riêng. Đây là không gian chốn yên bình dành cho những ai muốn khám phá nét độc đáo trong từng ngụm cà phê đúng chuẩn.', 'Its upper floors hold a distinct coffee aroma, where creative minds come looking for inspiration amid raw, industrial surroundings. From carefully selected beans to every cup poured with real care, every detail here tells its own story. This is a calm space for anyone who wants to discover something special in every well-crafted sip of coffee.', 'Quán specialty coffee đầu tiên và nổi tiếng nhất Sài Gòn — không gian công nghiệp thoáng rộng 3 tầng, hội tụ giới creative và freelancer.', 'Saigon''s first and most famous specialty coffee shop, a spacious 3-story industrial space that draws in creatives and freelancers.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/the-workshop-coffee/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/the-workshop-coffee/1.jpg', true, false, true, '2026-07-23T13:26:06.903962+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('1aee091c-3a1f-44c4-a9a7-58f4fb9de37a', 'Tòa nhà Landmark 81 & Đài quan sát Landmark 81 SkyView', 'Landmark 81 & Landmark 81 SkyView Observatory', 'SG', 'Bình Thạnh', '720A Điện Biên Phủ, P. 22, Q. Bình Thạnh (KĐT Vinhomes Central Park)', 'Trải nghiệm', 'Check-in, Về đêm, Nhộn nhịp', ARRAY['Check-in','Về đêm','Nhộn nhịp']::text[], 3, 300000, 90, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=T%C3%B2a%20nh%C3%A0%20Landmark%2081%20%26%20%C4%90%C3%A0i%20quan%20s%C3%A1t%20Landmark%2081%20SkyView%2C%20B%C3%ACnh%20Th%E1%BA%A1nh%2C%20TP.%20H%E1%BB%93%20Ch%C3%AD%20Minh', '{"lat": 10.7949, "lng": 106.7218}'::jsonb, 'Tòa tháp cao nhất Việt Nam và top 20 thế giới (461.3m) lấy cảm hứng từ bó tre truyền thống vươn lên mây xanh. Đài quan sát SkyView tầng 79 - 81 trang bị cầu kính SkyTouch trong suốt ở độ cao gần 400m, trải nghiệm game nhảy dù thực tế ảo và góc nhìn 360 độ toàn thành phố. Lên đài quan sát trước hoàng hôn 30 phút để bắt trọn 2 khoảnh khắc tuyệt mỹ: hoàng hôn buông trên sông Sài Gòn và thành phố lên đèn rực rỡ.', 'Vietnam''s tallest tower and one of the world''s top 20 (461.3m), inspired by a traditional bundle of bamboo reaching up into the clouds. The SkyView observatory on floors 79-81 features the transparent SkyTouch glass bridge at nearly 400m up, plus a virtual-reality skydiving experience and a 360-degree view of the whole city. Head up 30 minutes before sunset to catch two stunning moments back to back: the sun setting over the Saigon River, and the city lighting up below.', 'Tòa tháp cao nhất Việt Nam và top 20 thế giới (461.3m) lấy cảm hứng từ bó tre truyền thống vươn lên mây xanh. Đài quan sát SkyView tầng 79 - 81 trang bị cầu kính SkyTouch trong suốt ở độ cao gần 400m, trải nghiệm game nh', 'Vietnam''s tallest tower and one of the world''s top 20 (461.3m), inspired by a traditional bundle of bamboo reaching up into the clouds.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/toa-nha-landmark-81-dai-quan-sat-landmark-81-skyview/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/toa-nha-landmark-81-dai-quan-sat-landmark-81-skyview/1.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('1205c0de-40cc-45d7-86ad-9921fee10774', 'Tòa tháp Bitexco Financial Tower & Saigon Skydeck', 'Bitexco Financial Tower & Saigon Skydeck', 'SG', 'Quận 1', 'Số 02 Hải Triều / 36 Hồ Tùng Mậu, P. Bến Nghé, Quận 1', 'Trải nghiệm', 'Check-in, Về đêm, Nhộn nhịp', ARRAY['Check-in','Về đêm','Nhộn nhịp']::text[], 3, 200000, 60, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=T%C3%B2a%20th%C3%A1p%20Bitexco%20Financial%20Tower%20%26%20Saigon%20Skydeck%2C%20Qu%E1%BA%ADn%201%2C%20TP.%20H%E1%BB%93%20Ch%C3%AD%20Minh', '{"lat": 10.7715, "lng": 106.7041}'::jsonb, 'Tòa tháp cao 262m gồm 68 tầng hình búp sen thanh thoát vươn lên với bãi đỗ trực thăng vươn ra ở tầng 52. Đài quan sát Saigon Skydeck tầng 49 trang bị ống nhòm viễn vọng tầm xa ngắm bao quát sông Sài Gòn, bến Nhà Rồng, bán đảo Thủ Thiêm và quận 1 từ trên cao. Có thể lên quán cafe/lounge ở tầng 50-52 để vừa thưởng thức đồ uống vừa ngắm trọn vẹn cảnh đêm lung linh của thành phố hoa lệ.', 'A 262m, 68-story tower shaped like a graceful rising lotus bud, with a helipad jutting out from the 52nd floor. The Saigon Skydeck observatory on the 49th floor is equipped with long-range telescopes for sweeping views over the Saigon River, Nha Rong Wharf, the Thu Thiem peninsula, and District 1 from high above. Head up to the cafe/lounge on floors 50-52 to sip a drink while taking in the city''s dazzling night view in full.', 'Tòa tháp cao 262m gồm 68 tầng hình búp sen thanh thoát vươn lên với bãi đỗ trực thăng vươn ra ở tầng 52. Đài quan sát Saigon Skydeck tầng 49 trang bị ống nhòm viễn vọng tầm xa ngắm bao quát sông Sài Gòn, bến Nhà Rồng, bá', 'A 262m, 68-story tower shaped like a graceful rising lotus bud, with a helipad jutting out from the 52nd floor.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/toa-thap-bitexco-financial-tower-saigon-skydeck/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/toa-thap-bitexco-financial-tower-saigon-skydeck/1.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00'),
  ('fbe2a1d2-0c08-4711-b234-e50b5f584981', 'Trụ sở HĐND & UBND TP. Hồ Chí Minh', 'Ho Chi Minh City People''s Council & People''s Committee Headquarters', 'SG', 'Quận 1', '86 Lê Thánh Tôn, P. Bến Nghé, Quận 1', 'Di tích lịch sử', 'Lịch sử, Hoài cổ, Kiến trúc', ARRAY['Lịch sử','Hoài cổ','Kiến trúc']::text[], 1, 0, 20, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=Tr%E1%BB%A5%20s%E1%BB%9F%20H%C4%90ND%20%26%20UBND%20TP.%20H%E1%BB%93%20Ch%C3%AD%20Minh%2C%20Qu%E1%BA%ADn%201%2C%20TP.%20H%E1%BB%93%20Ch%C3%AD%20Minh', '{"lat": 10.7765, "lng": 106.7009}'::jsonb, 'Công trình biểu tượng xây dựng từ 1898-1909 mang kiến trúc Phục Hưng phương Tây với tháp chuông nhô cao ở giữa, mặt tiền đắp nổi tượng nữ thần Marianne và hoa văn baroque tinh xảo. Phía trước là Quảng trường tượng đài Chủ tịch Hồ Chí Minh uy nghiêm. Đứng từ giữa đài phun nước hoa sen trên phố đi bộ Nguyễn Huệ để lấy trọn vẹn tượng đài Bác Hồ và toàn cảnh mặt tiền lung linh của tòa nhà.', 'An iconic building constructed from 1898 to 1909 in Western Renaissance style, with a central bell tower, a facade adorned with relief sculptures of the goddess Marianne, and intricate baroque motifs. In front stands the dignified Ho Chi Minh Monument Square. Stand at the lotus fountain on Nguyen Hue walking street to frame the Ho Chi Minh statue together with the building''s full, glittering facade.', 'Công trình biểu tượng xây dựng từ 1898-1909 mang kiến trúc Phục Hưng phương Tây với tháp chuông nhô cao ở giữa, mặt tiền đắp nổi tượng nữ thần Marianne và hoa văn baroque tinh xảo. Phía trước là Quảng trường tượng đài Ch', 'An iconic building constructed from 1898 to 1909 in Western Renaissance style, with a central bell tower, a facade adorned with relief sculptures of the goddess Marianne, and intricate baroque motifs.', NULL, 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/tru-so-hdnd-ubnd-tp-ho-chi-minh/1.jpg', '{}', 'https://viloca-media.s3.ap-southeast-1.amazonaws.com/locations/SG/tru-so-hdnd-ubnd-tp-ho-chi-minh/1.jpg', true, false, true, '2026-10-21T15:55:46.324556+00:00', '2026-10-24T16:35:44.807117+00:00')
